// ============================================
// DATI CARTE - ARMY_SETS e ARMY_DECKS
// ============================================

export const ARMY_SETS = {
    // === FIGLI DELL'ORIZZONTE === (Tema: Controllo VA, Focus Coin, cosmico)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Figli dell'Orizzonte": [
      { id: 101, name: "Sorethal, il Primo Ancorante", league: 5, power: 6, damage: 4, icon: "galaxy", ability: { trigger: "overdrive", effect: "enemyAssault", value: -8, minAssault: 6 }, description: "Potere: Overdrive: -8 VA nem. (min 6)", flavour: "La Fusione dissolse i corpi, ma Sorethal rifiutò di svanire. Si vestì di reliquie del vecchio mondo — armature vuote, armi dimenticate — e scoprì che la materia attutiva la Domanda. Fu il primo ad ancorarsi. Fu il primo a restare intero." },
      { id: 111, name: "L'Eco del Primo Sole", league: 5, power: 5, damage: 5, icon: "explosion", ability: { trigger: "turbo", effect: "assaultValue", value: 8 }, description: "Potere: Turbo: +8 VA", flavour: "Il sole di Vaelith morì durante la Fusione. Qualcosa del suo ultimo respiro si condensò — non caldo, non luminoso, ma con la memoria di esserlo stato. Quando vince, per un istante, il sistema ricorda la luce." },
      { id: 116, name: "Vega, il Sofferente", league: 5, power: 4, damage: 5, icon: "circle", ability: { trigger: "ultimaChance", effect: "power", value: 4 }, description: "Potere: Ultima Chance: +4 POT", flavour: "Non riuscì a dissolversi. Mentre gli altri svanivano nella Nebula, lui restava — ogni tentativo fallito aggiungeva un altro strato, un altro frammento, un'altra domanda compressa nella massa. Non è diventato un Pesante. È diventato qualcosa che non ha nome. Quando arriva, il campo trema." },
      { id: 102, name: "Tessitrice della Trama", league: 4, power: 4, damage: 3, icon: "sparkle", ability: { trigger: "sopraffare", effect: "focusCoin", value: 2 }, description: "Potere: Sopraffare: +2 FC", flavour: "I Tessitori credono che l'universo sia un arazzo in costante creazione. Lei ne tiene i fili — e quando un Figlio si sfilaccia, le sue mani d'ombra lo ricuciono nel tessuto del reale." },
      { id: 103, name: "Portatore della Domanda", league: 4, power: 4, damage: 4, icon: "moon", ability: { trigger: "reckoning", effect: "enemyAssault", value: -8, minAssault: 8 }, description: "Potere: Resa dei conti: -8 VA nem. (min 8)", flavour: "Non combatte con armi. Combatte con dubbio. Chi lo affronta sente la Domanda Senza Fine insinuarsi: 'Cosa sono? Perché combatto? Cosa sto proteggendo?' — e per un istante, dimentica." },
      { id: 105, name: "Richiamante dell'Ordine", league: 4, power: 5, damage: 3, icon: "sunrise", ability: { trigger: "turbo", effect: "directDamage", value: 2 }, description: "Potere: Turbo: 2 Danni dir.", flavour: "Quando un Leggero si disperde troppo, lui lo afferra. Tira il filo invisibile che li collega alla Nebula e lo forza a condensarsi. È un sollievo agonizzante — ma è meglio del vuoto." },
      { id: 112, name: "Serath, Che Mangia il Dopo", league: 4, power: 5, damage: 3, icon: "hole", ability: { trigger: "reckoning", effect: "blockAbility", value: null }, description: "Potere: Resa dei conti: Blocca Potere", flavour: "Non divora il presente — divora il futuro. Chi lo affronta sente le proprie possibilità restringersi, le vie di fuga chiudersi. Quando siete pari, non c'è più nulla dopo di lui." },
      { id: 117, name: "Prete dell'Ancora", league: 4, power: 5, damage: 2, icon: "pray", ability: { trigger: "rinforzi", effect: "damage", value: 3 }, description: "Potere: Rinforzi: +3 DAN", flavour: "L'Ordine dell'Ancora non ha templi — ha pratiche. Lui insegna la prima: vincere è l'unica preghiera che la Nebula ascolta. Ogni vittoria deposita qualcosa di solido dove la Domanda aveva rosicchiato. Non è fede. È sopravvivenza con un nome più dignitoso." },
      { id: 104, name: "Cartografo del Vuoto", league: 3, power: 3, damage: 3, icon: "sparkle", ability: { trigger: "opportunista", effect: "focusCoin", value: 3 }, description: "Potere: Opportunista: +3 FC", flavour: "Mappa i confini del reame — confini che si espandono ogni volta che li raggiunge. Non cerca una destinazione. Cerca il punto esatto dove l'esistenza finisce e il nulla inizia." },
      { id: 106, name: "Condensato per la Guerra", league: 3, power: 1, damage: 4, icon: "comet", ability: { trigger: null, effect: "attrition", value: 1, stat: "power" }, description: "Potere: Attrizione 1 POT", flavour: "Era disperso nella Nebula, perso nella Domanda. Poi i Pesanti lo tirarono e gli diedero una spada. Combatte con ferocia — non per odio, ma perché combattere significa essere, e essere significa non soffrire." },
      { id: 113, name: "L'Ultimo Specchio di Oris", league: 3, power: 1, damage: 4, icon: "mirror", ability: { trigger: "resistenza", effect: "copyPower", value: null }, description: "Potere: Resistenza: Copia POT nem.", flavour: "Era uno specchio nel palazzo reale — fino a quando la Fusione lo svegliò. Ora cammina, e riflette ancora. Ma gli specchi non scelgono cosa mostrare. Mostrano la verità, anche quando fa male." },
      { id: 114, name: "Il Portatore della Campana", league: 3, power: 4, damage: 3, icon: "wave", ability: { trigger: "glory", effect: "powerAndDamage", value: 1 }, description: "Potere: Gloria: +1 POT, +1 DAN", flavour: "La campana del tempio di Oris non suonò mai durante la Fusione — nessuno la toccò. Lui la porta sulla schiena da allora. È pesante. È inutile. È l'unica cosa che lo tiene intero." },
      { id: 118, name: "Cometa alla Deriva", league: 3, power: 5, damage: 1, icon: "comet", ability: { trigger: null, effect: "escalation", value: 1, stat: "damage" }, description: "Potere: Escalation: +1 DAN", flavour: "Non sa dove sta andando. Lo sa da sempre. Ma qualcosa nella traiettoria — qualcosa nell'accelerazione — sembra una risposta. Forse la Domanda si risolve nell'impatto. Forse diventa abbastanza veloce da non sentirla più." },
      { id: 119, name: "Vittima della Domanda", league: 3, power: 3, damage: 3, icon: "eye", ability: { trigger: "reckoning", effect: "enemyAssault", value: -6, minAssault: 6 }, description: "Potere: Resa dei conti: -6 VA nem. (min 6)", flavour: "Non combatte con odio. Non combatte con paura. Combatte con la Domanda stessa — la proietta, la condivide, la trasmette. Chi la affronta impara cosa significa non sapere cosa si è. E in quel momento di dubbio, il campo è già perduto." },
      { id: 107, name: "Eco Svanente", league: 2, power: 3, damage: 1, icon: "rocket", ability: { trigger: null, effect: "blockBonus", value: null }, description: "Potere: Blocca Bonus", flavour: "Una volta era qualcuno. Un nome, una storia, un posto nel mondo. Ora è solo un'eco — abbastanza presente da esistere, troppo sbiadita per ricordare cosa fosse. E chi le sta vicino inizia a sbiadire anche lui." },
      { id: 108, name: "Leggero Richiamato", league: 2, power: 3, damage: 1, icon: "crystal", ability: { trigger: "ultimaChance", effect: "directDamage", value: 4 }, description: "Potere: Ultima Chance: 4 Danni dir.", flavour: "Lo hanno tirato fuori dal vuoto, costretto in una forma che non ricordava. Combatte perché non ha scelta. Ma quando cade, torna alla Nebula — e il rilascio è un'onda che brucia chi sta vicino." },
      { id: 109, name: "Naela, la Prima Sognatrice", league: 2, power: 3, damage: 1, icon: "eye", ability: { trigger: "rimonta", effect: "power", value: 2 }, description: "Potere: Rimonta: +2 POT", flavour: "Fu tra i primi a sognare l'orizzonte. Convinse altri a seguirla nella Nebula. Ora porta i loro volti sulla pelle — e quando cade, sono loro a rialzarla." },
      { id: 110, name: "Ashara, la Volontaria", league: 2, power: 2, damage: 2, icon: "star", ability: { trigger: "imboscata", effect: "power", value: 2 }, description: "Potere: Imboscata: +2 POT", flavour: "Non aspettò la Fusione. Camminò nella Nebula con gli occhi aperti, prima degli altri. Pensava di diventare qualcosa di più. Divenne qualcosa di meno — ma abbastanza da trascinare i nemici con sé." },
      { id: 115, name: "Vethan, Guerriero per un Giorno", league: 2, power: 3, damage: 1, icon: "insect", ability: { trigger: "conquest", effect: "focusCoin", value: 2 }, description: "Potere: Conquista: +2 FC", flavour: "I Leggeri richiamati durano poco — ore, al massimo giorni. Lui lo sa. Combatte comunque, perché ogni momento di forma è un momento senza la Domanda. E se deve soffrire, preferisce che anche il nemico soffra." },
      { id: 120, name: "Richiamato Smantellato", league: 2, power: 3, damage: 1, icon: "pickaxe", ability: { trigger: "imboscata", effect: "enemyDamage", value: -2, minDamage: 3 }, description: "Potere: Imboscata: -2 DAN nem. (min 3)", flavour: "Lo hanno tirato fuori dalla Nebula in fretta. Mancano pezzi — un braccio, metà del torso, la memoria di cosa facesse con quelle parti. Combatte lo stesso. Non perché sia coraggioso. Perché fermarsi significherebbe ricominciare a chiedersi cosa è." },
      { id: 121, name: "Fine del Pensiero", league: 2, power: 1, damage: 3, icon: "hole", ability: { trigger: "ultimaChance", effect: "imponiPower", value: null }, description: "Potere: Ultima Chance: Imponi POT", flavour: "Quando la Domanda ha consumato tutto il resto, resta solo questo: un punto fermo dove il pensiero finisce e la forma obbedisce." },
      { id: 122, name: "Nidhogg", league: 3, power: 2, damage: 4, icon: "dragon", ability: { trigger: "invasione", effect: "power", value: 3 }, description: "Potere: Invasione: +3 POT", flavour: "Si avvolge intorno ai confini conquistati e rosicchia ciò che resta solido. Ogni campo preso gli dà un altro anello da stringere." },
      { id: 123, name: "Pesante Centenario", league: 3, power: 3, damage: 3, icon: "circle", ability: { trigger: "intervention", effect: "enemyDamage", value: -2, minDamage: 2 }, description: "Potere: Intervento: -2 DAN nem. (min 2)", flavour: "Cent'anni di massa condensata. Quando entra dopo il primo impatto, il nemico scopre che la gravità ha anche un peso morale." },
      { id: 124, name: "Timoniere del Vuoto", league: 3, power: 4, damage: 2, icon: "comet", ability: { trigger: "intervention", effect: "assaultValue", value: 5 }, description: "Potere: Intervento: +5 VA", flavour: "Non guida navi — guida assenza. Quando arriva secondo, ricalibra la traiettoria e il campo intero inclina verso di lui." },
      { id: 125, name: "Satellite della Nebula", league: 3, power: 5, damage: 1, icon: "ufo", ability: { trigger: "imboscata", effect: "damage", value: 2 }, description: "Potere: Imboscata: +2 DAN", flavour: "Orbita silenziosa finché qualcuno non guarda altrove. Poi cade — piccolo, preciso, troppo tardi per schivarlo." },
      { id: 126, name: "Collezionista di Spade", league: 4, power: 2, damage: 1, icon: "sword", ability: { trigger: null, effect: "attrition", value: 1, stat: "powerAndDamage" }, description: "Potere: Attrizione 1 POT, 1 DAN", flavour: "Ogni lama raccolta è una vittoria rubata al passato. Quando avanza, il nemico sente il peso di tutte quelle sconfitte accumulate." },
      { id: 127, name: "Arsenale Vivente", league: 4, power: 2, damage: 4, icon: "arm", ability: { trigger: "resistenza", effect: "assaultValue", value: 12 }, description: "Potere: Resistenza: +12 VA", flavour: "Non porta armi: ne è una. Quando il fronte cede, si apre e rilascia tutto ciò che ha inghiottito — in una sola scarica di assalto." },
      { id: 128, name: "Divoramenti", league: 4, power: 4, damage: 3, icon: "devil", ability: { trigger: "imboscata", effect: "power", value: 2 }, description: "Potere: Imboscata: +2 POT", flavour: "Attacca per primo e non lascia frammenti. Ciò che inghiotte non va nella Nebula — va nel duello, subito, intero." },
      { id: 129, name: "O-Etemorp", league: 4, power: 5, damage: 2, icon: "mirror", ability: { trigger: "rimonta", effect: "damage", value: 3 }, description: "Potere: Rimonta: +3 DAN", flavour: "La sua forma non è fissa: è risposta. Quando resta indietro, impara dal colpo subito e lo restituisce moltiplicato." },
      { id: 130, name: "Astronave da Guerra della Nebula", league: 5, power: 6, damage: 3, icon: "rocket", ability: { trigger: "imboscata", effect: "blockBonus", value: null }, description: "Potere: Imboscata: Blocca Bonus", flavour: "Prima ancora che il nemico possa reagire, i suoi cannoni spezzano ogni vantaggio. Non è un blitz — è una eclissi controllata." }
    ],
  
    // === KETHRAN === (Tema: POT, vendetta, aggressività)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Kethran": [
      { id: 201, name: "Ur-Nammu il Conquistatore", league: 5, power: 6, damage: 5, icon: "crown", ability: { trigger: "magnanimous", effect: "power", value: 2 }, description: "Potere: Magnanimo: +2 POT", flavour: "Era re prima della caduta. Nel buio, rifiutò di morire — prese i pezzi migliori dei suoi sudditi caduti, uno per uno. 'Un re porta il suo popolo' disse. Ora li porta letteralmente. E loro combattono ancora per lui." },
      { id: 211, name: "Nimrod, il Primo Re", league: 5, power: 5, damage: 3, icon: "temple", ability: { trigger: "reckoning", effect: "powerAndDamage", value: 2 }, description: "Potere: Resa dei conti: +2 POT, +2 DAN", flavour: "Quando cercò vendetta, i Velessi erano polvere. I Tharim, un ricordo. La Coalizione, cenere. Non trovò nessuno da uccidere — così prese i loro pezzi dalle tombe. Ora porta i suoi nemici dentro di sé. E li fa soffrire ogni giorno." },
      { id: 202, name: "Profeta delle Rovine", league: 4, power: 4, damage: 3, icon: "scroll", ability: { trigger: "vendetta", effect: "damage", value: 2 }, description: "Potere: Vendetta: +2 DAN", flavour: "Prima dell'Inversione leggeva le stelle. Ora legge i frammenti — ossa, pietre, pezzi di chi non c'è più. Ogni rovina racconta una storia. La sua storia preferita è quella della vendetta che verrà." },
      { id: 212, name: "Spirito della Spira", league: 4, power: 4, damage: 4, icon: "ghost", ability: { trigger: "sopraffare", effect: "immune", value: null }, description: "Potere: Sopraffare: Immune", flavour: "Non è un Kethran — è la Spira stessa, condensata in carne. Quando tutto sembra perduto, lui non può cadere. La torre è già caduta una volta. Non cade due volte." },
      { id: 213, name: "Eco del Tradimento", league: 4, power: 2, damage: 5, icon: "copy", ability: { trigger: null, effect: "escalation", value: 2, stat: "power" }, description: "Potere: Escalation 2 POT", flavour: "Porta i pezzi di Varethi — non il traditore intero, ma frammenti sparsi tra i morti dell'Inversione. Nessuno sa quali pezzi siano suoi. Ma quando lei parla, i nemici sentono dubbio. E il dubbio uccide." },
      { id: 203, name: "Araldo della Fine", league: 4, power: 4, damage: 3, icon: "horn", ability: { trigger: "glory", effect: "directDamage", value: 3 }, description: "Potere: Gloria: 3 Danni dir.", flavour: "Il suo corno è fatto delle gole di dodici cantori, fuse insieme. Suona una sola nota — la nota che udirono quando la Spira sprofondò. Chi la sente ricorda cosa significa cadere." },
      { id: 204, name: "Custode della Ziqqurat", league: 3, power: 4, damage: 2, icon: "temple", ability: { trigger: null, effect: "blockBonus", value: null }, description: "Potere: Blocca Bonus", flavour: "Sorvegliava i gradini che salivano al cielo. Ora sorveglia quelli che scendono nel buio. Ogni passo verso la Spira passa davanti a lui — e lui decide chi è degno di entrare." },
      { id: 205, name: "Sacerdote della Ricomposizione", league: 3, power: 3, damage: 3, icon: "flame", ability: { trigger: "sfida", effect: "power", value: 2 }, description: "Potere: Sfida: +2 POT", flavour: "L'ordine è l'illusione di chi non è mai stato spezzato. Lui insegna la verità: i pezzi si trovano, si uniscono, diventano qualcosa di nuovo. E quel qualcosa è sempre più forte." },
      { id: 206, name: "Berserker della Spira", league: 3, power: 4, damage: 3, icon: "angry", ability: { trigger: "vendetta", effect: "powerAndDamage", value: 1 }, description: "Potere: Vendetta: +1 POT, +1 DAN", flavour: "Non ricorda chi era prima della caduta. Non ricorda i nomi dei pezzi che porta. Ricorda solo la rabbia — e la rabbia è abbastanza. Quando lo colpisci, ricorda anche di più." },
      { id: 214, name: "Il Primo Mattone", league: 3, power: 5, damage: 1, icon: "brick", ability: { trigger: "conquest", effect: "selfDamage", value: 2 }, description: "Potere: Conquista: -2 PV (a te)", flavour: "Quando ricostruirono nel buio, qualcuno doveva essere la base. Lui si sdraiò e disse 'Costruite su di me'. Non si è più alzato — ma non ha mai ceduto." },
      { id: 207, name: "Seguace Fanatico", league: 2, power: 3, damage: 1, icon: "pray", ability: { trigger: "glory", effect: "power", value: 2 }, description: "Potere: Gloria: +2 POT", flavour: "Morirà mille volte se questo significa vedere la Spira risalire. E ogni volta che vince, crede di essere più vicino. Non lo è — ma la fede lo rende più forte." },
      { id: 208, name: "Costruttore Maledetto", league: 2, power: 3, damage: 2, icon: "pickaxe", ability: { trigger: "imboscata", effect: "escalation", value: 1, stat: "damage" }, description: "Potere: Imboscata: Escalation 1 DAN", flavour: "Le sue mani costruirono la Spira — livello dopo livello, pietra dopo pietra. Dopo l'Inversione, quelle mani non erano più le sue. Ma ricordano ancora come smontare ciò che toccano." },
      { id: 209, name: "Ombra della Spira", league: 2, power: 2, damage: 3, icon: "tower", ability: { trigger: "resistenza", effect: "enemyAssault", value: -6, minAssault: 5 }, description: "Potere: Resistenza: -6 VA nem. (min 5)", flavour: "I Kethran lo mandano avanti, dove la luce non arriva. Torna sempre con qualcosa — informazioni, pezzi, nemici silenziati. Ogni vittoria significa che il buio è ancora suo alleato." },
      { id: 210, name: "Martire della Spira", league: 2, power: 2, damage: 2, icon: "skull", ability: { trigger: "lastWish", effect: "directDamage", value: 3 }, description: "Potere: Ultimo desiderio: 3 Danni dir.", flavour: "Si è offerto sapendo che sarebbe morto. Ha chiesto solo una cosa: che la sua morte facesse male a qualcuno. I Kethran mantengono sempre le promesse ai loro martiri." },
      { id: 215, name: "Ultimo Testimone", league: 2, power: 3, damage: 1, icon: "eye", ability: { trigger: "lastWish", effect: "heal", value: 2 }, description: "Potere: Ultimo desiderio: Cura 2", flavour: "Ha visto la Spira in piedi. Ha visto l'Inversione. Ha visto il buio, la ricomposizione, la risalita. Quando cade, i suoi occhi — tutti e sette — vanno a chi ne ha bisogno. Continueranno a vedere." },
      { id: 216, name: "Crepuscolo, l'Assassino di Soli", league: 5, power: 7, damage: 3, icon: "skull", ability: { trigger: "conquest", effect: "selfDamage", value: 4 }, description: "Potere: Conquista: -4 PV (a te)", flavour: "Non combatte per vincere. Combatte per restare nel buio — quello stato di dolore lucido dove ogni cosa è più nitida, più vera, più letale. Ogni vittoria è un coltello che si gira da solo. Lo vuole comunque." },
      { id: 217, name: "Chimera", league: 4, power: 2, damage: 5, icon: "insect", ability: { trigger: null, effect: "enemyPower", value: -4, minPower: 3 }, description: "Potere: Sempre: -4 POT nem. (min 3)", flavour: "Non ha volontà. Non ha nome proprio — Chimera è ciò che i Kethran chiamano qualcosa che non sanno come chiamare altrimenti. Gli arti si muovono. Gli occhi guardano. I denti mordono. Nessuno sa perché. Nemmeno lei." },
      { id: 218, name: "Frammento del Conquistatore", league: 3, power: 2, damage: 3, icon: "crown", ability: { trigger: "rimonta", effect: "copyPower", value: null }, description: "Potere: Rimonta: Copia POT nem.", flavour: "Porta un braccio di Ur-Nammu — non quello originale, ma uno dei tanti che il Re aveva integrato. La forza passa di mano in mano. Non si disperde mai." },
      { id: 219, name: "La Marea Composita", league: 3, power: 3, damage: 3, icon: "wave", ability: { trigger: "reckoning", effect: "damage", value: 3 }, description: "Potere: Resa dei conti: +3 DAN", flavour: "Quando ne abbatti uno, altri tre raccolgono i pezzi. Non stai combattendo una creatura. Stai combattendo un processo." },
      { id: 220, name: "Mezzanotte, il Mai Nato", league: 2, power: 3, damage: 2, icon: "ghost", ability: { trigger: null, effect: "inversion", value: null }, description: "Potere: Inversione", flavour: "Erede della volontà di Crepuscolo, il buio che colpì la Spira quel giorno ne soffocò anche l'oscurità promessa. Nacque a metà — abbastanza da riflettere, non abbastanza da esistere del tutto. Ciò che ti lanci contro torna indietro. Non perché lo voglia. Perché non sa fare altro." },
      { id: 221, name: "Glauson il Secondo Architetto", league: 2, power: 2, damage: 2, icon: "brick", ability: { trigger: "rimonta", effect: "powerAndDamage", value: 1 }, description: "Potere: Rimonta: +1 POT, +1 DAN", flavour: "Dopo la caduta della Spira, qualcuno doveva ridisegnare ciò che restava. Lui non ricostruisce muri — ricostruisce possibilità, pezzo dopo pezzo, finché il nemico non regge più." },
      { id: 222, name: "La Luccicante", league: 3, power: 3, damage: 2, icon: "sparkle", ability: { trigger: "lastWish", effect: "focusCoin", value: 2 }, description: "Potere: Ultimo desiderio: +2 FC", flavour: "Brilla anche nel buio sotto la Spira. Quando cade, lascia monete dove nessuno le aveva viste — come se la ricomposizione pagasse sempre qualcosa." },
      { id: 223, name: "Angelo Ricomposto", league: 3, power: 3, damage: 4, icon: "ghost", ability: { trigger: "rinforzi", effect: "imponiPower", value: null }, description: "Potere: Rinforzi: Imponi POT", flavour: "Non è nato intero. È stato assemblato da mani che non pregavano più — e quando arriva con i suoi pari, impone una sola legge: la forza deve obbedire." },
      { id: 224, name: "Cacciatore di Normoformi", league: 3, power: 4, damage: 2, icon: "eye", ability: { trigger: "imboscata", effect: "damage", value: 2 }, description: "Potere: Imboscata: +2 DAN", flavour: "Nel buio sotto la torre, tutto ciò che sembra normale è sospetto. Lui colpisce per primo — e ciò che resta non assomiglia più a nulla di umano." },
      { id: 225, name: "Guardiano dell'Altare della Ricomposizione", league: 3, power: 4, damage: 1, icon: "temple", ability: { trigger: "imboscata", effect: "blockAbility", value: null }, description: "Potere: Imboscata: Blocca Potere", flavour: "Sorveglia l'altare dove i pezzi tornano interi. Chi attacca per primo scopre che alcuni poteri non attraversano la soglia — si fermano lì, muti." },
      { id: 226, name: "Centauro Rivoltante", league: 4, power: 4, damage: 5, icon: "angry", ability: { trigger: "glory", effect: "enemyPower", value: -2, minPower: 3 }, description: "Potere: Gloria: -2 POT nem. (min 3)", flavour: "Metà uomo, metà bestia, tutto rancore. Quando vince, non celebra — spezza le ginocchia del nemico prima che possa rialzarsi." },
      { id: 227, name: "Tagliapietre", league: 4, power: 5, damage: 3, icon: "pickaxe", ability: { trigger: "vendetta", effect: "enemyDamage", value: -3, minDamage: 1 }, description: "Potere: Vendetta: -3 DAN nem. (min 1)", flavour: "Smonta muri, statue, nemici. Quando lo colpiscono, risponde togliendo ciò che rende pericoloso il colpo successivo." },
      { id: 228, name: "Verme Plotone", league: 4, power: 5, damage: 1, icon: "insect", ability: { trigger: "intervention", effect: "directDamage", value: 2 }, description: "Potere: Intervento: 2 Danni dir.", flavour: "Non combatte da solo — combatte in fila, sotto, dove nessuno guarda. Quando entra dopo il primo impatto, lascia un solco che brucia." },
      { id: 229, name: "Titano di Carne", league: 4, power: 5, damage: 3, icon: "arm", ability: { trigger: "overdrive", effect: "powerAndDamage", value: 1 }, description: "Potere: Overdrive: +1 POT, +1 DAN", flavour: "Non è pietra come la Spira — è carne ricucita, tendini e ossa rubate ai caduti. Quando spendi tutto, lui diventa abbastanza grande da reggere la caduta del nemico." },
      { id: 230, name: "Vicario Berakol, Maestro della Ricomposizione", league: 5, power: 4, damage: 4, icon: "scroll", ability: { trigger: "vendetta", effect: "powerAndDamage", value: 2 }, description: "Potere: Vendetta: +2 POT, +2 DAN", flavour: "Insegna che ogni frammento ha un posto. Quando lo ferisci, non si spezza — si riassembla più forte, e ti restituisce il doppio di ciò che gli hai tolto." }
    ],
  
    // === CORTE ROSSA === (Tema: Copia, blocco, manipolazione, patti)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Corte Rossa": [
      { id: 301, name: "Vaelith Sorn, il Primo", league: 5, power: 7, damage: 3, icon: "devil", ability: { trigger: "conquest", effect: "directDamage", value: 3 }, description: "Potere: Conquista: 3 Danni dir.", flavour: "Siedeva al centro dei tavoli quando Sethramis era solo una città. Ora siede al centro di tutto. Il prezzo? Lo vedi. Ne è valsa la pena? Chiedilo a lui. Non risponderà." },
      { id: 311, name: "Generale Karthessi", league: 5, power: 5, damage: 4, icon: "mirror", ability: { trigger: "reckoning", effect: "copyAbility", value: null }, description: "Potere: Resa dei conti: Copia Potere nem.", flavour: "Era il più grande guerriero del suo popolo. Poi firmò. Ora combatte per la Corte — con la stessa ferocia che un tempo era sua. Non ricorda di chi fosse." },
      { id: 302, name: "L'Estrattrice", league: 4, power: 4, damage: 3, icon: "snake", ability: { trigger: "intervention", effect: "copyAbility", value: null }, description: "Potere: Intervento: Copia Potere", flavour: "Va di persona a riscuotere. Non nasconde più cosa è diventata — il terrore fa parte del pagamento. Quando arriva, i debitori firmano qualsiasi cosa pur di farla andare via." },
      { id: 303, name: "Esattore Infernale", league: 4, power: 5, damage: 4, icon: "oni", ability: { trigger: "opportunista", effect: "enemyPower", value: -4, minPower: 3 }, description: "Potere: Opportunista: -4 POT nem. (min 3)", flavour: "Il debito viene sempre riscosso. Con l'oro, con il sangue, o con l'anima. La scelta, tecnicamente, è tua." },
      { id: 312, name: "Artigiano Velithari", league: 4, power: 5, damage: 3, icon: "sword", ability: { trigger: "vendetta", effect: "directDamage", value: 2 }, description: "Potere: Vendetta: 2 Danni dir.", flavour: "Forgiava armi per il suo popolo. Poi firmò — e le sue mani non furono più sue. Ora forgia per la Corte. Ogni lama che crea uccide un po' di ciò che era." },
      { id: 304, name: "Tentatore d'Anime", league: 3, power: 4, damage: 2, icon: "devil", ability: { trigger: "imboscata", effect: "blockAbility", value: null }, description: "Potere: Imboscata: Blocca Potere", flavour: "Offre sempre ciò che desideri di più. Il prezzo? Solo ciò che ami di più. Sembra uno scambio equo. Sembra sempre uno scambio equo." },
      { id: 305, name: "Avvocato del Diavolo", league: 3, power: 2, damage: 4, icon: "scales", ability: { trigger: "imboscata", effect: "copyPower", value: null }, description: "Potere: Imboscata: Copia POT", flavour: "Legalmente parlando, la tua anima non ti è mai appartenuta. Vedi, c'è questa clausola..." },
      { id: 306, name: "Giudice Corrotto", league: 3, power: 4, damage: 3, icon: "judge", ability: { trigger: "vendetta", effect: "blockBonus", value: null }, description: "Potere: Vendetta: Blocca Bonus", flavour: "Il suo verdetto è sempre lo stesso: colpevole. La sentenza varia — ma solo in base a quanto puoi pagare per ammorbidirla." },
      { id: 313, name: "Dammeri Spezzato", league: 3, power: 2, damage: 3, icon: "bomb", ability: { trigger: "invasione", effect: "enemyPower", value: -3, minPower: 2 }, description: "Potere: Invasione: -3 POT nem. (min 2)", flavour: "Era l'ultimo a resistere. Ha firmato ieri. Ora cammina con la Corte — e i nemici vedono in lui cosa li aspetta. La speranza muore dove lui passa." },
      { id: 314, name: "Debitore Trasformato", league: 3, power: 4, damage: 3, icon: "oni", ability: { trigger: "vendetta", effect: "powerAndDamage", value: 1 }, description: "Potere: Vendetta: +1 POT, +1 DAN", flavour: "Ha firmato per rabbia. Ha estratto per rabbia. La rabbia lo ha consumato — ora non è più nulla tranne rabbia. E la rabbia non si ferma mai." },
      { id: 307, name: "Archivista degli Obblighi", league: 2, power: 2, damage: 2, icon: "imp", ability: { trigger: "intervention", effect: "enemyDamage", value: -2, minDamage: 2 }, description: "Potere: Intervento: -2 DAN nem. (min 2)", flavour: "Ogni debito è registrato. Ogni promessa, catalogata. Lui sa cosa devi — anche se tu l'hai dimenticato. Specialmente se tu l'hai dimenticato." },
      { id: 308, name: "Messaggero Burlone", league: 2, power: 2, damage: 3, icon: "card", ability: { trigger: "imboscata", effect: "power", value: 2 }, description: "Potere: Imboscata: +2 POT", flavour: "Porta notizie — sempre cattive per qualcuno, sempre divertenti per lui. Il suo sorriso è l'ultima cosa che vedono i debitori prima che arrivino gli Esattori." },
      { id: 309, name: "Ombra del Creditore", league: 2, power: 3, damage: 2, icon: "bat", ability: { trigger: "imboscata", effect: "enemyPower", value: -2, minPower: 2 }, description: "Potere: Imboscata: -2 POT nem. (min 2)", flavour: "Dove va il padrone, lui segue. Ma non è un servo — è un promemoria. Chi vede la sua ombra sa che un debito sta per essere riscosso." },
      { id: 310, name: "Anima Dannata", league: 2, power: 3, damage: 1, icon: "skull", ability: { trigger: "sfida", effect: "powerAndDamage", value: 1 }, description: "Potere: Sfida: +1 POT, +1 DAN", flavour: "Una volta era un eroe. Poi ha stretto un patto. Ora è ciò che resta quando gli eroi scoprono il prezzo della vittoria." },
      { id: 315, name: "Larva della Corte", league: 2, power: 1, damage: 3, icon: "ghost", ability: { trigger: "intervention", effect: "power", value: 2 }, description: "Potere: Intervento: +2 POT", flavour: "Ogni demone inizia così — piccolo, debole, affamato. Mangia contratti, cresce, diventa. Un giorno sarà un Esattore. Per ora, è solo fame con le gambe." },
      { id: 316, name: "Airam, la Confortatrice", league: 5, power: 5, damage: 4, icon: "snake", ability: { trigger: null, effect: "inversion", value: null }, description: "Potere: Sempre: Inversione", flavour: "Si dice che dia il conforto ai deboli. Che esaudisca l'ultimo desiderio di chi sta per soccombere. Non è generosità — è l'ultimo servizio che un debitore può rendere prima che il conto sia chiuso." },
      { id: 317, name: "Banditore di Schiavi", league: 4, power: 6, damage: 2, icon: "clipboard", ability: { trigger: "intervention", effect: "blockAbility", value: null }, description: "Potere: Intervento: Blocca Potere", flavour: "Non gli interessa a chi. Gli interessa a quanto. Il prezzo è sempre equo — per lui." },
      { id: 318, name: "Fratello del Banditore di Schiavi", league: 4, power: 6, damage: 2, icon: "skull", ability: { trigger: "reckoning", effect: "directDamage", value: 2 }, description: "Potere: Resa dei conti: 2 Danni dir.", flavour: "Nessuno sa il suo nome. Si sa solo che si muove quando le parole del fratello non sono bastate. Riscuote i debiti." },
      { id: 319, name: "Investigatore Demoniaco", league: 3, power: 4, damage: 1, icon: "scroll", ability: { trigger: "reckoning", effect: "blockAbility", value: null }, description: "Potere: Resa dei conti: Blocca Potere", flavour: "Indaga solo per confermare le tue colpe. E quando non trova prove, le crea." },
      { id: 320, name: "Messaggero Nefasto", league: 2, power: 3, damage: 1, icon: "card", ability: { trigger: "intervention", effect: "directDamage", value: 2 }, description: "Potere: Intervento: 2 Danni dir.", flavour: "Quando lo vedi arrivare, è già troppo tardi. Sarà una pessima esistenza da quel momento." },
      { id: 321, name: "Raccogli Firme", league: 2, power: 3, damage: 1, icon: "scroll", ability: { trigger: "rinforzi", effect: "power", value: 2 }, description: "Potere: Rinforzi: +2 POT", flavour: "Non chiede il consenso — lo raccoglie. Ogni firma è un filo, e quando tira, la forza arriva da tutte le direzioni insieme." },
      { id: 322, name: "Il Postillatore", league: 3, power: 3, damage: 1, icon: "book", ability: { trigger: "rimonta", effect: "enemyAssault", value: -10, minAssault: 8 }, description: "Potere: Rimonta: -10 VA nem. (min 8)", flavour: "Annota ogni errore del nemico nel margine del contratto. Quando resti indietro, le clausole si stringono — e l'assalto avversario diventa illeggibile." },
      { id: 323, name: "Phimesto", league: 3, power: 4, damage: 2, icon: "devil", ability: { trigger: "rinforzi", effect: "blockBonus", value: null }, description: "Potere: Rinforzi: Blocca Bonus", flavour: "Sorride mentre controlla la mano iniziale. Se c'è un vantaggio nascosto, lo trova — e lo cancella prima che possa servire." },
      { id: 324, name: "Litilis la Mutevole", league: 3, power: 5, damage: 1, icon: "mirror", ability: { trigger: "intervention", effect: "copyDamage", value: null }, description: "Potere: Intervento: Copia DAN", flavour: "Non ha una forma fissa — ha forme prestabilite nel contratto. Quando entra seconda, indossa il danno del nemico come un vestito che le sta sempre a pennello." },
      { id: 325, name: "Gemelli Samsara", league: 3, power: 4, damage: 3, icon: "copy", ability: { trigger: "glory", effect: "enemyPower", value: -2, minPower: 2 }, description: "Potere: Gloria: -2 POT nem. (min 2)", flavour: "Due volti, un solo registro. Quando vinci, uno sorride e l'altro firma — e il nemico scopre di aver già perso qualcosa che non sapeva di possedere." },
      { id: 326, name: "Sigillatore dei Vili Affari", league: 4, power: 5, damage: 3, icon: "block", ability: { trigger: "rinforzi", effect: "blockAbility", value: null }, description: "Potere: Rinforzi: Blocca Potere", flavour: "Chiude ogni patto con cera e silenzio. Se nella mano c'è un alleato della stessa lega, i poteri avversari restano sigillati finché lui respira." },
      { id: 327, name: "Intrattenitore di Corte", league: 4, power: 5, damage: 4, icon: "card", ability: { trigger: "sopraffare", effect: "power", value: 2 }, description: "Potere: Sopraffare: +2 POT", flavour: "Fa ridere finché non fa male. Quando sei in vantaggio, la sua performance diventa minacciosa — ogni applauso è un colpo in più." },
      { id: 328, name: "La Clausola di Revoca", league: 4, power: 4, damage: 4, icon: "scales", ability: { trigger: "intervention", effect: "enemyPower", value: -3, minPower: 2 }, description: "Potere: Intervento: -3 POT nem. (min 2)", flavour: "Esiste in ogni contratto della Corte, anche quando nessuno l'ha scritta. Quando entra in gioco, revoca la forza che credevi di possedere." },
      { id: 329, name: "Nosterafu il Contabile", league: 4, power: 5, damage: 3, icon: "clipboard", ability: { trigger: "reckoning", effect: "enemyAssault", value: -6, minAssault: 5 }, description: "Potere: Resa dei conti: -6 VA nem. (min 5)", flavour: "Non combatte — fa quadratura. Quando il conto è pari, chiude i libri e toglie al nemico ogni margine di manovra rimasto." },
      { id: 330, name: "Alira l'Usuraia di Corone", league: 5, power: 8, damage: 1, icon: "crown", ability: { trigger: "invasione", effect: "copyDamage", value: null }, description: "Potere: Invasione: Copia DAN", flavour: "Non prende oro — prende titoli. Quando avanza, il nemico scopre che il suo danno non era mai stato suo. Era solo in prestito, con interessi." }
    ],
  
    // === CALIBRI PESANTI === (Tema: Difesa, riduzione danno, immune, resistenza)
    // Lega Totale: 73 (4×L5 · 9×L4 · 10×L3 · 8×L2)
    "Calibri Pesanti": [
      { id: 401, name: "Titano Corazzato MK-IV", league: 5, power: 5, damage: 6, icon: "🤖", ability: { trigger: "reckoning", effect: "immune", value: null }, description: "Potere: Resa dei conti: Immune", flavour: "I primi tre modelli fallirono. Il quarto imparò dai loro errori. E da quelli di tutti coloro che cercarono di fermarlo." },
      { id: 411, name: "Protocollo Cenere", league: 5, power: 4, damage: 4, icon: "antenna", ability: { trigger: "sopraffare", effect: "directDamage", value: 4 }, description: "Potere: Sopraffare: 4 Danni dir.", flavour: "Attivato solo quando tutto fallisce. Quando i piani sono cenere — come Kyrath. Quando resta solo la resistenza. Allora lui si sveglia. E ricomincia da zero." },
      { id: 402, name: "Nucleo di Comando Nord", league: 4, power: 5, damage: 3, icon: "brain", ability: { trigger: "overdrive", effect: "power", value: 2 }, description: "Potere: Overdrive: +2 POT", flavour: "Il fronte nord non è mai caduto. Lui è il motivo. Coordina, calcola, comanda — e quando serve, scende in campo. Il nemico non sa cosa sia peggio." },
      { id: 403, name: "Bastione Ambulante", league: 4, power: 4, damage: 4, icon: "castle", ability: { trigger: "overdrive", effect: "focusCoin", value: 3 }, description: "Potere: Overdrive: +3 FC", flavour: "Metà del suo corpo è ancora quello con cui è nato. L'altra metà è ciò che serviva per sopravvivere. Non sa più quale metà sia davvero lui." },
      { id: 412, name: "Pugno del Fronte Ovest", league: 4, power: 6, damage: 2, icon: "sword", ability: { trigger: "magnanimous", effect: "powerAndDamage", value: 1 }, description: "Potere: Magnanimo: +1 POT, +1 DAN", flavour: "Nord comanda. Est vede. Sud ascolta. Ovest colpisce. Quando arriva il momento, non serve strategia — serve forza. E Ovest è tutta la forza di Kyrath in un solo pugno." },
      { id: 413, name: "Cannone Semovente", league: 4, power: 5, damage: 3, icon: "explosion", ability: { trigger: "overdrive", effect: "directDamage", value: 3 }, description: "Potere: Overdrive: 3 Danni dir.", flavour: "Costa caro da alimentare. Ma quando spara, nessuno si lamenta del prezzo." },
      { id: 404, name: "Tecnico di Prima Linea", league: 3, power: 4, damage: 1, icon: "wrench", ability: { trigger: "vendetta", effect: "heal", value: 2 }, description: "Potere: Vendetta: Cura 2", flavour: "Non combatte. Non fugge. Resta dove serve — tra i feriti, tra i caduti, tra i pezzi. Li rimette insieme. A volte funziona. A volte no. Sempre ci prova." },
      { id: 405, name: "Guardiano di Settore", league: 3, power: 4, damage: 2, icon: "arm", ability: { trigger: "sfida", effect: "blockAbility", value: null }, description: "Potere: Sfida: Blocca Potere", flavour: "Gli hanno assegnato un settore. Non sa più quale. Non importa — difende tutto ciò che vede. Tutto ciò che si muove è una minaccia. Finché non dimostra il contrario." },
      { id: 406, name: "Analista da Combattimento", league: 3, power: 2, damage: 3, icon: "lightning", ability: { trigger: null, effect: "attrition", value: 1, stat: "power" }, description: "Potere: Attrizione 1 POT", flavour: "Analizza. Replica. Supera. Tre secondi. È tutto il tempo di cui ha bisogno." },
      { id: 414, name: "Raccoglitore del Campo", league: 3, power: 4, damage: 3, icon: "pickaxe", ability: { trigger: "glory", effect: "focusCoin", value: 2 }, description: "Potere: Gloria: +2 FC", flavour: "Non distingue tra amici e nemici. Pezzi sono pezzi. Un braccio funzionante è un braccio funzionante — non importa a chi apparteneva. Importa a chi servirà." },
      { id: 415, name: "Protocollo di Emergenza", league: 3, power: 4, damage: 1, icon: "alert", ability: { trigger: "resistenza", effect: "powerAndDamage", value: 1 }, description: "Potere: Resistenza: +1 POT, +1 DAN", flavour: "Sistemi critici attivati. Modalità sopravvivenza: online. Eliminazione minacce: in corso." },
      { id: 407, name: "Drone Cacciatore X-9", league: 2, power: 3, damage: 1, icon: "ufo", ability: { trigger: "imboscata", effect: "directDamage", value: 2 }, description: "Potere: Imboscata: 2 Danni dir.", flavour: "Progettato per la ricognizione. Riprogrammato per l'intercettazione. Perfezionato per l'eliminazione." },
      { id: 408, name: "Operaio Meccanico", league: 2, power: 2, damage: 2, icon: "gear", ability: { trigger: "rinforzi", effect: "enemyDamage", value: -2, minDamage: 2 }, description: "Potere: Rinforzi: -2 DAN nem. (min 2)", flavour: "Costruisce armi giorno e notte. Non perché gli sia ordinato, ma perché ha dimenticato come costruire qualsiasi altra cosa." },
      { id: 409, name: "Occhio del Fronte Est", league: 2, power: 2, damage: 1, icon: "insect", ability: { trigger: "vendetta", effect: "power", value: 2 }, description: "Potere: Vendetta: +2 POT", flavour: "Vede tutto. Colpisce da lontano. Ma quando il nemico arriva vicino — quando il primo colpo lo trova — qualcosa si sveglia. Qualcosa di meno preciso. E molto più letale." },
      { id: 410, name: "Orecchio del Fronte Sud", league: 2, power: 3, damage: 2, icon: "antenna", ability: { trigger: "lastWish", effect: "focusCoin", value: 2 }, description: "Potere: Ultimo desiderio: +2 FC", flavour: "Decisero di usare parti del corpo per identificare i propri ruoli, una tradizione che divenne un terribile memento." },
      { id: 416, name: "Il Chirurgo", league: 5, power: 7, damage: 2, icon: "robot", ability: { trigger: "rimonta", effect: "heal", value: 3 }, description: "Potere: Rimonta: Cura 3", flavour: "Fu il primo ad unire l'uomo alle macchine. Dopo di lui il suo ruolo passò di successore in successore — un lascito che divenne un titolo, un titolo che divenne una condanna." },
      { id: 417, name: "Santo Motore", league: 4, power: 5, damage: 4, icon: "gear", ability: { trigger: "rinforzi", effect: "assaultValue", value: 8 }, description: "Potere: Rinforzi: +8 VA", flavour: "Benedice le macchine prima che escano dalla fabbrica. Prima che partano in missione. Prima che vengano smantellate. Non distingue tra le tre cerimonie — per lui sono la stessa cosa." },
      { id: 418, name: "Morto che Vola", league: 3, power: 3, damage: 3, icon: "explosion", ability: { trigger: "lastWish", effect: "directDamage", value: 2 }, description: "Potere: Ultimo desiderio: 2 Danni dir.", flavour: "Comunque vada lasciano il loro segno. Il segno di una volontà e di un sacrificio oramai indistinguibile dallo spirito indomito umano." },
      { id: 419, name: "K-9.1", league: 2, power: 3, damage: 2, icon: "robot", ability: { trigger: "ultimaChance", effect: "power", value: 3 }, description: "Potere: Ultima Chance: +3 POT", flavour: "Non abbaia. Non morde. Calcola. L'ultima funzione rimasta attiva quando tutto il resto si spegne è quella per cui era stato costruito: avanzare." },
      { id: 420, name: "Sistema Balistico Poco Accurato", league: 2, power: 2, damage: 2, icon: "explosion", ability: { trigger: "overdrive", effect: "power", value: 3 }, description: "Potere: Overdrive: +3 POT", flavour: "Nessuno sa dove atterreranno. Neanche loro. L'importante è che atterrino da qualche parte — preferibilmente sul nemico, ma non è una condizione necessaria." },
      { id: 421, name: "Trenobomba", league: 2, power: 3, damage: 1, icon: "explosion", ability: { trigger: "turbo", effect: "assaultValue", value: 6 }, description: "Potere: Turbo: +6 VA", flavour: "Non è un treno. Non è una bomba. È entrambe le cose, e arriva sempre in orario — se per orario intendi troppo presto." },
      { id: 422, name: "Guardia del Centralino", league: 3, power: 4, damage: 2, icon: "antenna", ability: { trigger: "invasione", effect: "directDamage", value: 2 }, description: "Potere: Invasione: 2 Danni dir.", flavour: "Quando il segnale diventa rosso, nessuno entra e nessuno esce. Tranne i proiettili." },
      { id: 423, name: "Prototipo Instabile", league: 3, power: 5, damage: 3, icon: "lightning", ability: { trigger: "lastWish", effect: "selfDamage", value: 4 }, description: "Potere: Ultimo desiderio: -4 PV (a te)", flavour: "Serie zero, lotto uno. Funziona. A volte funziona troppo." },
      { id: 424, name: "Protocollo Silenzio", league: 3, power: 4, damage: 3, icon: "block", ability: { trigger: "vendetta", effect: "enemyPower", value: -2, minPower: 2 }, description: "Potere: Vendetta: -2 POT nem. (min 2)", flavour: "Quando cade, spegne tutto. Motori, armi, speranze. L'ultima cosa che senti è il click del relè." },
      { id: 425, name: "Punitore di Settore", league: 3, power: 4, damage: 2, icon: "arm", ability: { trigger: "invasione", effect: "blockBonus", value: null }, description: "Potere: Invasione: Blocca Bonus", flavour: "Ogni settore ha le sue regole. La sua regola è semplice: niente vantaggi per chi invade." },
      { id: 426, name: "Spargifuoco", league: 4, power: 4, damage: 3, icon: "flame", ability: { trigger: "resistenza", effect: "enemyAssault", value: -12, minAssault: 8 }, description: "Potere: Resistenza: -12 VA nem. (min 8)", flavour: "Quando il fronte cede, lui brucia la traiettoria. Il nemico può ancora avanzare — ma più lentamente, e molto più caldo." },
      { id: 427, name: "K-13.4", league: 4, power: 5, damage: 2, icon: "robot", ability: { trigger: "reckoning", effect: "enemyPowerAndDamage", value: -1, minPower: 3, minDamage: 3 }, description: "Potere: Resa dei conti: -1 POT, -1 DAN nem. (min 3)", flavour: "Calcola, misura, corregge. Quando entrambi hanno giocato abbastanza, toglie esattamente ciò che serve per riequilibrare — a tuo favore." },
      { id: 428, name: "Bombardiere Ali Argentee", league: 4, power: 4, damage: 4, icon: "ufo", ability: { trigger: "resistenza", effect: "escalation", value: 2, stat: "power" }, description: "Potere: Resistenza: Escalation 2 POT", flavour: "Più il cielo si riempie di fumo, più le ali argentee trovano bersagli. Resistere non significa restare fermi." },
      { id: 429, name: "Divora-bossoli", league: 4, power: 5, damage: 2, icon: "gear", ability: { trigger: "resistenza", effect: "attrition", value: 1, stat: "directDamage" }, description: "Potere: Resistenza: Attrizione 1 Danni dir.", flavour: "Ogni carta che hai già giocato lascia un bossolo. Lui li raccoglie tutti — e li restituisce a chi sta vincendo troppo." },
      { id: 430, name: "Obice Campione", league: 5, power: 4, damage: 6, icon: "antenna", ability: { trigger: "overdrive", effect: "escalation", value: 10, stat: "assaultValue" }, description: "Potere: Overdrive: Escalation +10 VA", flavour: "Sopra Kyrath qualcosa guarda sempre. Quando spendi abbastanza, punta. Quando punta, il campo sotto non ha più scuse." }
    ],
  
    // === ORATHAI === (Tema: Magia, potenza arcana, equilibrio)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Orathai": [
      { id: 501, name: "Voce della Fine", league: 5, power: 5, damage: 4, icon: "moon", ability: { trigger: "glory", effect: "power", value: 2 }, description: "Potere: Gloria: +2 POT", flavour: "I Vuoti vengono chiamati quando tutto fallisce. Lui viene chiamato quando i Vuoti non bastano. Il suo canto non ferisce — cancella. Dove lui canta, il suono stesso muore dopo." },
      { id: 511, name: "La Tempesta Cava", league: 5, power: 6, damage: 2, icon: "copy", ability: { trigger: "overdrive", effect: "assaultValue", value: 12 }, description: "Potere: Overdrive: +12 VA", flavour: "Si è svuotato per diventare strumento. Legno, aria, risonanza — nient'altro. Il suo canto non ha limite perché lui non ha più limiti." },
      { id: 502, name: "Radice dei Caduti", league: 4, power: 5, damage: 3, icon: "sparkle", ability: { trigger: "resistenza", effect: "focusCoin", value: 2 }, description: "Potere: Resistenza: +2 FC", flavour: "Le sue radici cercano i caduti prima ancora che tocchino terra. Non per rispetto — per fame. Il canto dei morti lo nutre." },
      { id: 503, name: "L'Eco Vivente", league: 4, power: 6, damage: 2, icon: "book", ability: { trigger: "magnanimous", effect: "damage", value: 2 }, description: "Potere: Magnanimo: +2 DAN", flavour: "Il suo corpo è la partitura. Ogni crepa, ogni nodo, ogni venatura — una nota del primo canto. Quando risuona, il bosco intero ricorda." },
      { id: 512, name: "Il Parassita Armonico", league: 4, power: 3, damage: 4, icon: "mirror", ability: { trigger: "intervention", effect: "copyPower", value: null }, description: "Potere: Intervento: Copia POT nem.", flavour: "Si avvolge al nemico e ascolta. Sente la frequenza, la impara, la ruba. Quando lascia andare, la vittima è vuota — e lui canta con una voce nuova." },
      { id: 504, name: "La Spina nel Bosco", league: 3, power: 4, damage: 3, icon: "vortex", ability: { trigger: "rinforzi", effect: "blockBonus", value: null }, description: "Potere: Rinforzi: Blocca Bonus", flavour: "Il bosco ha imparato a difendersi. Lui è la lezione — dolce da lontano, letale da vicino. Nessuno attraversa senza lasciare qualcosa tra le spine." },
      { id: 505, name: "L'Albero della Linfa d'Oro", league: 3, power: 4, damage: 1, icon: "eye", ability: { trigger: "conquest", effect: "focusCoin", value: 3 }, description: "Potere: Conquista: +3 FC", flavour: "Quando canta la vittoria, la linfa scorre. Dorata, calda, preziosa. Gli altri Orathai si avvicinano a bere — e il bosco intero diventa più forte." },
      { id: 506, name: "Il Cacciatore Paziente", league: 3, power: 5, damage: 1, icon: "wizard", ability: { trigger: "imboscata", effect: "power", value: 2 }, description: "Potere: Imboscata: +2 POT", flavour: "La pazienza è il suo canto. Silenzioso, lento, eterno. Quando finalmente si muove, è già troppo tardi per qualsiasi risposta." },
      { id: 513, name: "Il Canto della Cenere", league: 3, power: 4, damage: 1, icon: "flame", ability: { trigger: "vendetta", effect: "heal", value: 2 }, description: "Potere: Vendetta: Cura 2", flavour: "Non teme il fuoco. Non teme la fine. Sa che la cenere è fertile — e il suo canto la trasforma. Dove altri vedono distruzione, lui vede opportunità." },
      { id: 514, name: "L'Albero dei Trofei", league: 3, power: 3, damage: 3, icon: "crystal", ability: { trigger: "invasione", effect: "power", value: 2 }, description: "Potere: Invasione: +2 POT", flavour: "Il bosco ricicla tutto. Lui più di tutti — i vinti diventano parte di lui. Le loro forme, i loro canti, le loro forze. Non è crudeltà. È onore." },
      { id: 507, name: "Il Germoglio Ostinato", league: 2, power: 3, damage: 1, icon: "cat", ability: { trigger: "sfida", effect: "toxin", value: 1, minHealth: 18 }, description: "Potere: Sfida: Tossina 1 (min 18)", flavour: "Piccolo, dicono. Debole, pensano. Poi lo colpiscono — e scoprono che il bosco non dimentica. Il bosco non perdona." },
      { id: 508, name: "Il Muschio Curativo", league: 2, power: 3, damage: 1, icon: "book", ability: { trigger: "resistenza", effect: "heal", value: 2 }, description: "Potere: Resistenza: Cura 2", flavour: "La sua melodia è lenta, dolce, come pioggia tra le foglie. Chi la sente guarisce — il muschio cresce sulle ferite seguendo le note, punto per punto." },
      { id: 509, name: "Il Seme Finale", league: 2, power: 3, damage: 1, icon: "sparkle", ability: { trigger: "lastWish", effect: "focusCoin", value: 2 }, description: "Potere: Ultimo desiderio: +2 FC", flavour: "Il suo ultimo canto non è un lamento. È una promessa — il seme che custodisce fiorirà, e dal suo legno nasceranno altri. Niente muore davvero nel bosco." },
      { id: 510, name: "La Guida del Bosco", league: 2, power: 2, damage: 1, icon: "dove", ability: { trigger: "glory", effect: "power", value: 3 }, description: "Potere: Gloria: +3 POT", flavour: "Canta piano, un richiamo che solo gli Orathai sentono. Li guida attraverso il buio, oltre il pericolo, fino alla vittoria. Poi canta più forte — e il bosco risponde." },
      { id: 515, name: "Il Fiore della Vittoria", league: 2, power: 1, damage: 3, icon: "lightning", ability: { trigger: "magnanimous", effect: "power", value: 3 }, description: "Potere: Magnanimo: +3 POT", flavour: "Lo vedono solo i vincitori. Per i perdenti, resta chiuso, invisibile, inesistente. Fiorisce solo per chi merita di vederlo." },
      { id: 516, name: "Il Coro", league: 5, power: 5, damage: 3, icon: "book", ability: { trigger: "vendetta", effect: "heal", value: 3 }, description: "Potere: Vendetta: Cura 3", flavour: "Non è un canto di vittoria. È un canto di resistenza — quello che rimane quando tutto il resto tace. Quando lo colpisci, risuona. Quando risuona, ricorda. E ciò che ricorda, guarisce." },
      { id: 517, name: "La Radice del Rancore", league: 4, power: 5, damage: 3, icon: "pickaxe", ability: { trigger: "reckoning", effect: "directDamage", value: 2 }, description: "Potere: Resa dei conti: 2 Danni dir.", flavour: "Si estende sottoterra, silenzioso, paziente. Quando emerge è perché ha deciso che è abbastanza — per tutti." },
      { id: 518, name: "Il Custode del Silenzio", league: 4, power: 5, damage: 2, icon: "block", ability: { trigger: "magnanimous", effect: "blockBonus", value: null }, description: "Potere: Magnanimo: Blocca Bonus", flavour: "Quando canta, il bosco tace. Quando il bosco tace, il nemico non ha più vantaggi — solo il freddo." },
      { id: 519, name: "L'Occhio del Bosco", league: 3, power: 4, damage: 2, icon: "eye", ability: { trigger: "imboscata", effect: "damage", value: 2 }, description: "Potere: Imboscata: +2 DAN", flavour: "Non colpisce. Indica. Quando ha trovato il punto debole, si fa da parte — e lascia che il bosco faccia il resto." },
      { id: 520, name: "Il Soffocatore Silente", league: 2, power: 1, damage: 1, icon: "insect", ability: { trigger: null, effect: "attrition", value: 1, stat: "power" }, description: "Potere: Attrizione 1 POT", flavour: "Comincia piccolo. Quasi invisibile. Poi un giorno ti svegli e non c'è più niente che non sia lui." },
      { id: 521, name: "Orathai Vorace", league: 2, power: 2, damage: 2, icon: "vortex", ability: { trigger: "rinforzi", effect: "directDamage", value: 3 }, description: "Potere: Rinforzi: 3 Danni dir.", flavour: "Pianta carnivora del bosco: dolce finché non apre la bocca. Quando nella mano c'è un compagno della stessa lega, le spine volano prima ancora del duello." },
      { id: 522, name: "Protettore degli Animali", league: 3, power: 4, damage: 2, icon: "wolf", ability: { trigger: "rinforzi", effect: "assaultValue", value: 7 }, description: "Potere: Rinforzi: +7 VA", flavour: "Leone del sottobosco, muscoli di radici e criniera di foglie. Quando la mano iniziale porta rinforzi, carica come i leoni da combattimento di un mondo che il bosco ricorda a metà." },
      { id: 523, name: "Bombarda-latrati", league: 3, power: 4, damage: 1, icon: "explosion", ability: { trigger: "intervention", effect: "directDamage", value: 2 }, description: "Potere: Intervento: 2 Danni dir.", flavour: "Lancia vasi d'argilla pieni di semi e polvere. Quando entra secondo, il nemico scopre che la ceramica del bosco esplode sempre al momento sbagliato." },
      { id: 524, name: "Sylwajuck l'Estremo", league: 3, power: 3, damage: 4, icon: "wizard", ability: { trigger: "magnanimous", effect: "power", value: 3 }, description: "Potere: Magnanimo: +3 POT", flavour: "Leshen delle profondità verdi: corna di legno, occhi di muschio, voce di tempesta lontana. Quando vince contro un avversario più debole, il bosco gli presta la forza dei caduti." },
      { id: 525, name: "Protettore dei Protettori", league: 3, power: 5, damage: 1, icon: "dove", ability: { trigger: "resistenza", effect: "immune", value: null }, description: "Potere: Resistenza: Immune", flavour: "Cervo maestoso, corna come rami antichi. Quando il nemico conquista, lui non cede — il canto del bosco lo rende intoccabile, almeno per un istante." },
      { id: 526, name: "Regalità Baritonale", league: 4, power: 4, damage: 3, icon: "crystal", ability: { trigger: "rinforzi", effect: "power", value: 3 }, description: "Potere: Rinforzi: +3 POT", flavour: "Principe fungino dal cappello largo e voce profonda. Quando la mano porta compagni della stessa lega, il suo regno si espande — e con esso la potenza." },
      { id: 527, name: "Beatitudine", league: 4, power: 6, damage: 1, icon: "sunrise", ability: { trigger: "imboscata", effect: "enemyDamage", value: -2, minDamage: 1 }, description: "Potere: Imboscata: -2 DAN nem. (min 1)", flavour: "Ciliegio in un prato di girasoli — bellezza così perfetta che ferisce. Attacca per primo e il nemico dimentica come colpire forte." },
      { id: 528, name: "Ritualista del Fuoco", league: 4, power: 5, damage: 2, icon: "flame", ability: { trigger: "vendetta", effect: "power", value: 2 }, description: "Potere: Vendetta: +2 POT", flavour: "Genera dalla voce un drago di suono e fuoco. Quando lo colpiscono, la melodia diventa ruggito — e il bosco risponde con più forza." },
      { id: 529, name: "Il Custode del Rumore", league: 4, power: 4, damage: 4, icon: "wave", ability: { trigger: "turbo", effect: "power", value: 2 }, description: "Potere: Turbo: +2 POT", flavour: "Canta e suona un tamburo enorme di corteccia. Nei primi attimi del duello, il ritmo entra nelle ossa — e la potenza segue il battito." },
      { id: 530, name: "Il Dio Cadavere", league: 5, power: 4, damage: 4, icon: "skull", ability: { trigger: null, effect: "attrition", value: 1, stat: "power" }, description: "Potere: Attrizione 1 POT", flavour: "Trono vuoto in mezzo a un giardino rigoglioso. Non muove un dito — ma ogni carta che giochi lo nutre, e il bosco cresce intorno al suo silenzio." }
    ],
  
    // === MOUNTHBORN (ex Nati dalla Bocca) === (Tema: DAN diretto, aggressione, sacrificio)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Mounthborn": [
      { id: 601, name: "Regina della Colonia", league: 5, power: 6, damage: 4, icon: "crown", ability: { trigger: "reckoning", effect: "immune", value: null }, description: "Potere: Resa dei conti: Immune", flavour: "Milioni di figli. Un solo stomaco. Lei non mangia — loro mangiano per lei. Lei non caccia — loro cacciano per lei. Lei è solo Fame. E la Fame non muore mai." },
      { id: 611, name: "L'Evoluzione Finale", league: 5, power: 6, damage: 3, icon: "dino", ability: { trigger: "turbo", effect: "powerAndDamage", value: 1 }, description: "Potere: Turbo: +1 POT, +1 DAN", flavour: "Non è nato così. È diventato così — boccone dopo boccone, vittima dopo vittima. Tutto ciò che ha mangiato vive in lui. Tutto ciò che ha mangiato lo protegge." },
      { id: 602, name: "Bruto Corazzato", league: 4, power: 4, damage: 3, icon: "rhino", ability: { trigger: "vendetta", effect: "escalation", value: 1, stat: "damage" }, description: "Potere: Vendetta: Escalation 1 DAN", flavour: "I giovani lo guardano e vedono il futuro. I nemici lo guardano e vedono la fine. Lui non guarda nessuno — guarda solo dove colpire dopo." },
      { id: 603, name: "Divoratore di Menti", league: 4, power: 3, damage: 4, icon: "brain", ability: { trigger: "intervention", effect: "copyPower", value: null }, description: "Potere: Intervento: Copia POT", flavour: "Non vuole il tuo corpo. Vuole ciò che sai, ciò che puoi, ciò che sei. Dopo, il corpo è solo un guscio vuoto — e lui è qualcosa di più." },
      { id: 612, name: "Vedova Viola", league: 4, power: 5, damage: 2, icon: "tooth", ability: { trigger: "intervention", effect: "enemyPower", value: -3, minPower: 3 }, description: "Potere: Intervento: -3 POT nem. (min 3)", flavour: "Otto zampe, otto modi per tenerti fermo. Un morso, un modo per renderti inutile. Non mangia subito — aspetta che tu capisca quanto sei impotente." },
      { id: 604, name: "L'Apripista", league: 3, power: 4, damage: 2, icon: "wolf", ability: { trigger: "imboscata", effect: "powerAndDamage", value: 1 }, description: "Potere: Imboscata: +1 POT, +1 DAN", flavour: "È sempre il primo. Il primo a sentire la Fame, il primo a scattare, il primo a mordere. Lo sciame segue la scia di sangue che lascia." },
      { id: 605, name: "Il Sempre Affamato", league: 3, power: 6, damage: 1, icon: "tooth", ability: { trigger: "intervention", effect: "damage", value: 2 }, description: "Potere: Intervento: +2 DAN", flavour: "La Fame lo divora da dentro. Lui divora tutto il resto. Non c'è pace, non c'è sazietà. Solo il prossimo boccone. E il prossimo. E il prossimo." },
      { id: 606, name: "Il Seminatore di Rovina", league: 3, power: 4, damage: 1, icon: "insect", ability: { trigger: "conquest", effect: "directDamage", value: 2 }, description: "Potere: Conquista: 2 Danni dir.", flavour: "Lascia una scia. Non di sangue — di morte lenta. Il terreno annerisce, le piante marciscono, l'acqua diventa veleno. È il suo regalo ai vinti." },
      { id: 613, name: "Il Corno Vendicativo", league: 3, power: 3, damage: 3, icon: "insect", ability: { trigger: "rimonta", effect: "power", value: 2 }, description: "Potere: Rimonta: +2 POT", flavour: "Non conosce la ritirata. Non conosce la resa. Conosce solo il corno, la carica, e il suono delle corazze nemiche che si spezzano." },
      { id: 614, name: "L'Interrutore", league: 3, power: 4, damage: 2, icon: "insect", ability: { trigger: "intervention", effect: "blockAbility", value: null }, description: "Potere: Intervento: Blocca Potere", flavour: "Emette un ronzio che non senti — ma il tuo corpo sì. I muscoli non rispondono, i pensieri si confondono, i poteri svaniscono. Resta solo il panico." },
      { id: 607, name: "Larva Esplosiva", league: 2, power: 4, damage: 1, icon: "insect", ability: { trigger: "imboscata", effect: "selfDamage", value: 2 }, description: "Potere: Imboscata: -2 PV (a te)", flavour: "La Regina ne manda a decine. La maggior parte non torna. Quelle che vincono... beh, nemmeno loro tornano. Ma il nemico nemmeno." },
      { id: 608, name: "Larva Parassita", league: 2, power: 2, damage: 2, icon: "insect", ability: { trigger: "vendetta", effect: "attrition", value: 1, stat: "power" }, description: "Potere: Vendetta: Attrizione 1 POT", flavour: "Si attacca dove non puoi raggiungerla. Beve poco, ma beve sempre. Quando te ne accorgi, non hai più la forza di staccarla." },
      { id: 609, name: "Il Nido Ambulante", league: 2, power: 4, damage: 2, icon: "insect", ability: { trigger: "lastWish", effect: "selfDamage", value: 3 }, description: "Potere: Ultimo desiderio: -3 PV (a te)", flavour: "Non combatte per vincere. Combatte per arrivare abbastanza lontano. Quando muore, la colonia nasce dove lui è caduto. Anche se costa." },
      { id: 610, name: "L'Ago Nascosto", league: 2, power: 1, damage: 2, icon: "🦂", ability: { trigger: "imboscata", effect: "power", value: 2 }, description: "Potere: Imboscata: +2 POT", flavour: "Un colpo. Uno solo. Non ne serve un secondo. Si nasconde, aspetta, colpisce, sparisce. La preda cade dopo, quando lei è già lontana." },
      { id: 615, name: "Zanzara Furiosa", league: 2, power: 3, damage: 2, icon: "insect", ability: { trigger: "sfida", effect: "directDamage", value: 2 }, description: "Potere: Sfida: 2 Danni dir.", flavour: "Ronza attorno alla battaglia, aspettando di essere colpita. Sembra follia — finché non vedi quanto veloce guarisce dopo aver affondato il rostro in chi l'ha ferita." },
      { id: 616, name: "Guardia Reale della Guglia", league: 5, power: 5, damage: 4, icon: "insect", ability: { trigger: "intervention", effect: "enemyPower", value: -4, minPower: 3 }, description: "Potere: Intervento: -4 POT nem. (min 3)", flavour: "Prima di trovare il proprio nome trovò la prima vittima, prima di trovare il suo posto trovò un ordine, divorare." },
      { id: 617, name: "Scolopendra Ossea", league: 4, power: 5, damage: 1, icon: "insect", ability: { trigger: "rimonta", effect: "powerAndDamage", value: 1 }, description: "Potere: Rimonta: +1 POT, +1 DAN", flavour: "La colonia la tollera perché pulisce ciò che resta. La teme perché non si ferma quando finiscono i cadaveri. Non distingue tra alleato e nemico — distingue tra morto e ancora in piedi. La Fame non conosce lutto. È paziente." },
      { id: 618, name: "Il Flagello Chitinoso", league: 4, power: 4, damage: 3, icon: "explosion", ability: { trigger: "imboscata", effect: "assaultValue", value: 6 }, description: "Potere: Imboscata: +6 VA", flavour: "La coda non è un'arma. È un avvertimento. L'arma sono le chele — veloci, precise, già attorno al tuo collo prima che tu veda la coda muoversi." },
      { id: 619, name: "Il Bombardiere della Colonia", league: 3, power: 4, damage: 2, icon: "virus", ability: { trigger: "vendetta", effect: "directDamage", value: 2 }, description: "Potere: Vendetta: 2 Danni dir.", flavour: "Porta il veleno nel ventre. Quando cade, lo rilascia. Non è una sconfitta — è la consegna." },
      { id: 620, name: "Mangiaossa", league: 2, power: 3, damage: 1, icon: "insect", ability: { trigger: "invasione", effect: "powerAndDamage", value: 1 }, description: "Potere: Invasione: +1 POT, +1 DAN", flavour: "Alcuni di loro nascono conoscendo la fame prima del sole. Molti il secondo, non lo vedranno mai." },
      { id: 621, name: "Ape Ignobile", league: 2, power: 3, damage: 1, icon: "insect", ability: { trigger: "rinforzi", effect: "powerAndDamage", value: 1 }, description: "Potere: Rinforzi: +1 POT, +1 DAN", flavour: "Ape mostruosa dal volo irregolare e dalla mandibola troppo larga. Quando la mano porta rinforzi, punge due volte — potenza e dolore insieme." },
      { id: 622, name: "Moscouter", league: 3, power: 4, damage: 2, icon: "insect", ability: { trigger: "rinforzi", effect: "enemyAssault", value: -6, minAssault: 8 }, description: "Potere: Rinforzi: -6 VA nem. (min 8)", flavour: "Piccola, ronzante, obscene. Quando nella mano c'è un compagno della stessa lega, il suo ronzio spezza l'assalto nemico prima che decolli." },
      { id: 623, name: "Parassita Suicida", league: 3, power: 3, damage: 2, icon: "insect", ability: { trigger: "imboscata", effect: "directDamage", value: 2 }, description: "Potere: Imboscata: 2 Danni dir.", flavour: "Uccello preso da un parassita che comanda le ali. Attacca per primo e si lancia in picchiata — il corpo cade, il danno resta." },
      { id: 624, name: "Maledizione Insettiforme", league: 3, power: 4, damage: 2, icon: "insect", ability: { trigger: "invasione", effect: "enemyAssault", value: -8, minAssault: 10 }, description: "Potere: Invasione: -8 VA nem. (min 10)", flavour: "Locusta mostruosa che oscura il cielo a striscianti. Quando avanza, il nemico scopre che conquistare non basta — bisogna ancora volare." },
      { id: 625, name: "Matriarca Gentile", league: 3, power: 4, damage: 3, icon: "insect", ability: { trigger: "glory", effect: "heal", value: 2 }, description: "Potere: Gloria: Cura 2", flavour: "Regina dal sorriso morbido e dal ventre pieno di larve. Quando vince, non celebra — partorisce vita, e il campo si riempie di piccoli morsi." },
      { id: 626, name: "Famelica Bastarda", league: 4, power: 4, damage: 4, icon: "insect", ability: { trigger: "reckoning", effect: "powerAndDamage", value: 1 }, description: "Potere: Resa dei conti: +1 POT, +1 DAN", flavour: "Mantide religiosa mostruosa, preghiera e fame nello stesso gesto. Quando il conto è pari, le sue chele si chiudono più forte — per entrambi." },
      { id: 627, name: "Principe Formica", league: 4, power: 5, damage: 3, icon: "crown", ability: { trigger: "magnanimous", effect: "blockAbility", value: null }, description: "Potere: Magnanimo: Blocca Potere", flavour: "Altezzoso, chitinoso, regale nel modo in cui la colonia piega le regole. Quando vince contro chi è più debole, i poteri nemici non valgono più nulla." },
      { id: 628, name: "Mangia Incendi", league: 4, power: 5, damage: 3, icon: "insect", ability: { trigger: "sopraffare", effect: "damage", value: 2 }, description: "Potere: Sopraffare: +2 DAN", flavour: "Falena gigante mostruosa, ali come ceneri viventi. Quando sei in vantaggio, brucia più in fretta — e il danno segue la fiamma." },
      { id: 629, name: "Dominatrice dei Cieli", league: 4, power: 4, damage: 3, icon: "insect", ability: { trigger: "overdrive", effect: "directDamage", value: 3 }, description: "Potere: Overdrive: 3 Danni dir.", flavour: "Vespa gigante che domina l'aria sopra la colonia. Quando spendi tutto all'inizio, il pungiglione non chiede permesso — colpisce e basta." },
      { id: 630, name: "Insetto della Guerra", league: 5, power: 5, damage: 3, icon: "insect", ability: { trigger: "rimonta", effect: "powerAndDamage", value: 2 }, description: "Potere: Rimonta: +2 POT, +2 DAN", flavour: "Metà millepiedi, metà scorpione, tutto rosso e chitinoso. Quando resti indietro, la guerra non finisce — diventa più grande, più affilata, più tua." }
    ],
  
    // === L'ENCLAVE DELLE SCAGLIE === (Tema: Dominio, nobiltà draconica, tesori, fuoco)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "L'Enclave delle Scaglie": [
      { id: 701, name: "Patriarca dell'Enclave", league: 5, power: 7, damage: 3, icon: "🐉", ability: { trigger: "invasione", effect: "powerAndDamage", value: 1 }, description: "Potere: Invasione: +1 POT, +1 DAN", flavour: "\"Non combatte. Giudica. E il suo giudizio è sempre lo stesso: indegno.\" — Ultimo sussurro di un pretendente al trono" },
      { id: 711, name: "Drago Antico Addormentato", league: 5, power: 6, damage: 4, icon: "dragon2", ability: { trigger: "rimonta", effect: "immune", value: null }, description: "Potere: Rimonta: Immune", flavour: "Dorme da ere, avvolto nell'oro. Chi lo sveglia scopre che il tesoro era una trappola, e lui il cacciatore." },
      { id: 702, name: "Custode del Tesoro", league: 4, power: 4, damage: 3, icon: "crystal", ability: { trigger: "imboscata", effect: "escalation", value: 1, stat: "powerAndDamage" }, description: "Potere: Imboscata: Escalation 1 POT, 1 DAN", flavour: "Conta ogni moneta, ricorda ogni gemma. Quando qualcosa manca, non cerca il ladro. Aspetta che torni." },
      { id: 703, name: "Cavaliere del Wyrm", league: 4, power: 5, damage: 2, icon: "sword", ability: { trigger: "turbo", effect: "powerAndDamage", value: 1 }, description: "Potere: Turbo: +1 POT, +1 DAN", flavour: "La sua cavalcatura non ha nome. I nomi sono per creature che possono essere domate." },
      { id: 712, name: "Piromante della Corte", league: 4, power: 6, damage: 1, icon: "flame", ability: { trigger: "conquest", effect: "directDamage", value: 3 }, description: "Potere: Conquista: 3 Danni dir.", flavour: "\"Il fuoco non chiede permesso. Il fuoco prende.\" — Giuramento dei Piromanti" },
      { id: 713, name: "Divoratore d'Oro", league: 4, power: 3, damage: 3, icon: "coin", ability: { trigger: "overdrive", effect: "powerAndDamage", value: 2 }, description: "Potere: Overdrive: +2 POT, +2 DAN", flavour: "Sembra piccolo, quasi patetico. Poi gli lanci una moneta e capisci perché l'Enclave lo tiene a catena." },
      { id: 704, name: "Guardiano della Tana", league: 3, power: 4, damage: 3, icon: "shield", ability: { trigger: "resistenza", effect: "blockAbility", value: null }, description: "Potere: Resistenza: Blocca Potere", flavour: "Non attacca mai per primo. Non ne ha bisogno. Nella tana, le regole le fa lui." },
      { id: 705, name: "Predatore Alato", league: 3, power: 4, damage: 2, icon: "🦅", ability: { trigger: "imboscata", effect: "power", value: 2 }, description: "Potere: Imboscata: +2 POT", flavour: "L'ombra arriva prima del ruggito. Il ruggito arriva prima degli artigli. Gli artigli arrivano ultimi, ma sono gli unici che contano." },
      { id: 714, name: "Incantatore di Scaglie", league: 3, power: 3, damage: 3, icon: "sparkle", ability: { trigger: "invasione", effect: "focusCoin", value: 2 }, description: "Potere: Invasione: +2 FC", flavour: "Le sue scaglie cadono una a una, e ognuna vale più dell'oro. Morire, per lui, è solo un altro investimento." },
      { id: 715, name: "Araldo della Fiamma", league: 3, power: 2, damage: 3, icon: "horn", ability: { trigger: "glory", effect: "power", value: 3 }, description: "Potere: Gloria: +3 POT", flavour: "Porta notizie di vittoria. Solo di vittoria. Le sconfitte non sono degne di essere annunciate." },
      { id: 706, name: "Draghetto Famelico", league: 2, power: 3, damage: 1, icon: "🐉", ability: { trigger: "overdrive", effect: "power", value: 2 }, description: "Potere: Overdrive: +2 POT", flavour: "Piccolo, affamato, instancabile. Un giorno sarà un signore dell'Enclave. Oggi si accontenta degli avanzi." },
      { id: 707, name: "Scaglia Errante", league: 2, power: 2, damage: 2, icon: "feather", ability: { trigger: "vendetta", effect: "power", value: 2 }, description: "Potere: Vendetta: +2 POT", flavour: "Esiliato dall'Enclave, vaga solo. Ma il sangue draconico non dimentica, e quando colpisce, colpisce come un vero drago." },
      { id: 708, name: "Servo del Tesoro", league: 2, power: 3, damage: 2, icon: "user", ability: { trigger: "lastWish", effect: "focusCoin", value: 2 }, description: "Potere: Ultimo desiderio: +2 FC", flavour: "Non è un drago. Non sarà mai un drago. Ma conosce ogni moneta della camera del tesoro, e questo lo rende indispensabile." },
      { id: 709, name: "Sputafuoco Giovane", league: 2, power: 3, damage: 1, icon: "flame", ability: { trigger: "reckoning", effect: "powerAndDamage", value: 1 }, description: "Potere: Resa dei conti: +1 POT, +1 DAN", flavour: "Il suo fuoco non brucia ancora abbastanza per uccidere. Ma brucia abbastanza per far male." },
      { id: 710, name: "Uovo di Drago", league: 2, power: 1, damage: 4, icon: "egg", ability: { trigger: "ultimaChance", effect: "power", value: 3 }, description: "Potere: Ultima Chance: +3 POT", flavour: "\"Distruggere un uovo è facile. Affrontare ciò che ne uscirà, impossibile.\" — Proverbio dell'Enclave" },
      { id: 716, name: "Tiranno del Sottosuolo", league: 5, power: 6, damage: 3, icon: "dragon", ability: { trigger: "sopraffare", effect: "blockAbility", value: null }, description: "Potere: Sopraffare: Blocca Potere", flavour: "Non volò mai. Non ne ebbe bisogno — il mondo veniva da lui. Fu il primo a capire che la guerra non si vince in aria. Si vince sotto, dove nessuno guarda. Strisciava mentre gli altri volavano. Cadde mentre gli altri trionfavano. Insegnò più lui nella sconfitta di quanto gli altri abbiano mai insegnato nella vittoria." },
      { id: 717, name: "Dracoltoio", league: 4, power: 3, damage: 4, icon: "star", ability: { trigger: "glory", effect: "assaultValue", value: 12 }, description: "Potere: Gloria: +12 VA", flavour: "Si ciba delle carcasse. Attende con ansia la fine di una battaglia per farlo. E se qualcosa ancora si muove, presto scoprirà che era meglio non farlo." },
      { id: 718, name: "Nobili Viola", league: 3, power: 3, damage: 2, icon: "coin", ability: { trigger: "glory", effect: "enemyPower", value: -3, minPower: 3 }, description: "Potere: Gloria: -3 POT nem. (min 3)", flavour: "Dopo la violenza rimane la diplomazia. Ma ai coboldi non piace parlare — il drago che alberga in loro è semplicemente ancora quieto." },
      { id: 719, name: "Coboldo Irrequieto", league: 3, power: 4, damage: 1, icon: "flame", ability: { trigger: "conquest", effect: "directDamage", value: 3 }, description: "Potere: Conquista: 3 Danni dir.", flavour: "I coboldi in battaglia cercano la gloria che li farà diventare draghi. O vivranno abbastanza per invidiare chi ci riuscirà, o moriranno prima." },
      { id: 720, name: "Foderi Neri", league: 2, power: 2, damage: 2, icon: "sword", ability: { trigger: "imboscata", effect: "attrition", value: 1, stat: "power" }, description: "Potere: Imboscata: Attrizione 1 POT", flavour: "Hanno abbandonato il loro sogno di divenire draghi, chi contro la loro voglia chi no. In ogni caso ora seguono lo stesso obiettivo di prima — diventare ricchi e potenti." },
      { id: 721, name: "Re Carbone", league: 2, power: 2, damage: 1, icon: "crown", ability: { trigger: "sfida", effect: "power", value: 3 }, description: "Potere: Sfida: +3 POT", flavour: "Regna su ciò che resta dopo il fuoco. Non è molto — ma a chi sfida un titolo più alto, la cenere diventa trono." },
      { id: 722, name: "Praticante dell'Ascensione", league: 3, power: 3, damage: 3, icon: "sparkle", ability: { trigger: "magnanimous", effect: "assaultValue", value: 6 }, description: "Potere: Magnanimo: +6 VA", flavour: "Studia la forma del drago come un credente studia la preghiera. Quando è in vantaggio, il suo passo diventa più pesante — e il mondo fa spazio." },
      { id: 723, name: "Fanatico di Gioielli", league: 3, power: 3, damage: 1, icon: "crystal", ability: { trigger: "glory", effect: "attrition", value: 1, stat: "power" }, description: "Potere: Gloria: Attrizione 1 POT", flavour: "Ogni vittoria aggiunge un gioiello al suo manto. Ogni gioiello aggiunge peso al colpo successivo. L'Enclave lo tollera perché il tesoro cresce con lui." },
      { id: 724, name: "Macellai da Campo", league: 3, power: 4, damage: 1, icon: "sword", ability: { trigger: "intervention", effect: "enemyAssault", value: -5, minAssault: 9 }, description: "Potere: Intervento: -5 VA nem. (min 9)", flavour: "Arrivano dopo lo schianto iniziale. Non cercano gloria — cercano il punto esatto in cui la carica avversaria si spezza." },
      { id: 725, name: "Rossofiamma", league: 3, power: 3, damage: 2, icon: "flame", ability: { trigger: "sfida", effect: "power", value: 3 }, description: "Potere: Sfida: +3 POT", flavour: "La sua fiamma è rossa come l'orgoglio di chi sfida un nemico più nobile. Brucia più forte quando il sangue draconico sente il disprezzo." },
      { id: 726, name: "Giallotuono", league: 4, power: 5, damage: 4, icon: "lightning", ability: { trigger: "sfida", effect: "power", value: 3 }, description: "Potere: Sfida: +3 POT", flavour: "Il tuono giallo precede sempre il colpo. Quando sfida chi è sopra di lui, la tempesta non annuncia più la pioggia — annuncia la caduta." },
      { id: 727, name: "Crystallimux", league: 4, power: 4, damage: 2, icon: "crystal", ability: { trigger: "intervention", effect: "copyBonus", value: null }, description: "Potere: Intervento: Copia Bonus", flavour: "Il cristallo sulla fronte non riflette il volto — riflette la tecnica nemica. Entra secondo, impara, replica. L'Enclave lo chiama consigliere. I nemici lo chiamano errore." },
      { id: 728, name: "Generalissimo", league: 4, power: 5, damage: 3, icon: "horn", ability: { trigger: "rinforzi", effect: "enemyAssault", value: -8, minAssault: 5 }, description: "Potere: Rinforzi: -8 VA nem. (min 5)", flavour: "Comanda le schiere che non vede. Quando la mano iniziale porta rinforzi della stessa lega, la sua voce taglia la carica avversaria come una scaglia affilata." },
      { id: 729, name: "Prossimo all'Ascensione", league: 4, power: 4, damage: 2, icon: "dragon", ability: { trigger: "reckoning", effect: "powerAndDamage", value: 2 }, description: "Potere: Resa dei conti: +2 POT, +2 DAN", flavour: "Non è ancora un drago. Ma quando il conto è pari e la partita si allunga, la metamorfosi accelera — e il nemico scopre che mancava poco." },
      { id: 730, name: "Imperatore Purpureo", league: 5, power: 5, damage: 4, icon: "crown", ability: { trigger: "resistenza", effect: "enemyPower", value: -3, minPower: 4 }, description: "Potere: Resistenza: -3 POT nem. (min 4)", flavour: "Il porpora non è un colore — è una sentenza. Quando l'Enclave cede terreno, lui ricorda ai conquistatori che un trono non si prende: si difende fino all'ultima scaglia." }
    ],
  
    // === RATTI DELLA MEGERA === (Tema: Maledizioni, pestilenza, stregoneria, attrizione)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Ratti della Megera": [
      { id: 801, name: "La Megera Eterna", league: 5, power: 5, damage: 3, icon: "wizard", ability: { trigger: null, effect: "blockAbility", value: null }, description: "Potere: Blocca Potere", flavour: "\"Non lancia maledizioni. È la maledizione.\" — Ultimo appunto di uno studioso scomparso" },
      { id: 811, name: "Flagello della Colonia", league: 5, power: 4, damage: 3, icon: "rat", ability: { trigger: "reckoning", effect: "enemyPower", value: -4, minPower: 2 }, description: "Potere: Resa dei conti: -4 POT nem. (min 2)", flavour: "Dove passa lui, la forza abbandona i muscoli e la speranza abbandona i cuori. Non uccide: svuota." },
      { id: 802, name: "Dott. Rancido", league: 4, power: 5, damage: 2, icon: "skull", ability: { trigger: "intervention", effect: "enemyAssault", value: -10, minAssault: 4 }, description: "Potere: Intervento: -10 VA nem. (min 4)", flavour: "È il male che segue l'uomo o viceversa? Il dottore cerca ancora la sua risposta, paziente dopo paziente." },
      { id: 803, name: "Strega del Crepuscolo", league: 4, power: 4, damage: 3, icon: "moon", ability: { trigger: "glory", effect: "enemyPower", value: -3, minPower: 2 }, description: "Potere: Gloria: -3 POT nem. (min 2)", flavour: "Aspetta che il sole tramonti. Aspetta che tu sia sicuro di vincere. Poi sussurra, e tutto cambia." },
      { id: 812, name: "Sciamano dei Miasmi", league: 4, power: 5, damage: 3, icon: "wind", ability: { trigger: "imboscata", effect: "enemyDamage", value: -3, minDamage: 1 }, description: "Potere: Imboscata: -3 DAN nem. (min 1)", flavour: "I suoi fumi entrano nei polmoni prima che tu lo veda. Quando lo vedi, è già troppo tardi per colpire forte." },
      { id: 813, name: "Ser Rathreus", league: 4, power: 5, damage: 2, icon: "sword", ability: { trigger: "rimonta", effect: "power", value: 3 }, description: "Potere: Rimonta: +3 POT", flavour: "«Tradì il suo re per lei. Ora uccide chiunque non sia lei.» — cronaca di Birgherund" },
      { id: 804, name: "Untore Silenzioso", league: 3, power: 4, damage: 2, icon: "virus", ability: { trigger: "opportunista", effect: "toxin", value: 1, minHealth: 10 }, description: "Potere: Opportunista: Tossina 1 (min 10)", flavour: "Non parla mai. Non ne ha bisogno. Il suo tocco dice tutto ciò che c'è da dire." },
      { id: 805, name: "Grillo Parlante", league: 3, power: 4, damage: 1, icon: "insect", ability: { trigger: "intervention", effect: "enemyPower", value: -3, minPower: 2 }, description: "Potere: Intervento: -3 POT nem. (min 2)", flavour: "Dal momento in cui incroci il suo sguardo, sarà per sempre nella tua vita. Nei sogni, negli incubi, per strada." },
      { id: 814, name: "Divoratore di Speranza", league: 3, power: 5, damage: 1, icon: "devil", ability: { trigger: "lastWish", effect: "toxin", value: 1, minHealth: 10 }, description: "Potere: Ultimo desiderio: Tossina 1 (min 10)", flavour: "Puoi ucciderlo. Tutti possono ucciderlo. Ma il veleno nel suo ultimo respiro ti seguirà per sempre." },
      { id: 815, name: "Il Gondoliere", league: 3, power: 4, damage: 2, icon: "wave", ability: { trigger: "intervention", effect: "blockBonus", value: null }, description: "Potere: Intervento: Blocca Bonus", flavour: "Fu re di Aldmere, poi gondoliere. La corona non la depose mai: un re resta re, anche laggiù. Smise per primo di veder la luce del sole — un'altra bellezza competeva per quel posto." },
      { id: 806, name: "L'Innumerevole", league: 2, power: 3, damage: 1, icon: "rat", ability: { trigger: "ultimaChance", effect: "toxin", value: 1, minHealth: 10 }, description: "Potere: Ultima Chance: Tossina 1 (min 10)", flavour: "Uno non è niente. Dieci non sono niente. Ma non sono mai uno, e non sono mai dieci." },
      { id: 807, name: "Spia della Megera", league: 2, power: 3, damage: 1, icon: "eye", ability: { trigger: "imboscata", effect: "enemyAssault", value: -6, minAssault: 5 }, description: "Potere: Imboscata: -6 VA nem. (min 5)", flavour: "I suoi occhi sono ovunque. Quando attacchi, lei sa già dove, quando e come fallirai." },
      { id: 808, name: "Rigattiere Ossuto", league: 2, power: 3, damage: 2, icon: "🦴", ability: { trigger: "lastWish", effect: "directDamage", value: 2 }, description: "Potere: Ultimo desiderio: 2 Danni dir.", flavour: "Gli ha chiesto di costruire un ponte per lei. Quando finì il legno usò la pietra, poi i cadaveri dei suoi cari, poi la sua pelle — ma le ossa non sono mai finite." },
      { id: 809, name: "Omuncolo", league: 2, power: 2, damage: 2, icon: "insect", ability: { trigger: "reckoning", effect: "enemyPower", value: -2, minPower: 1 }, description: "Potere: Resa dei conti: -2 POT nem. (min 1)", flavour: "Sua madre è morta prima che potesse vederlo strisciare, e spera che un giorno possa volare fino a lei." },
      { id: 810, name: "Ratto Moribondo", league: 2, power: 3, damage: 2, icon: "rat", ability: { trigger: "opportunista", effect: "directDamage", value: 2 }, description: "Potere: Opportunista: 2 Danni dir.", flavour: "Vive della paura degli altri: più si agitano, più i suoi denti affondano. Non sopporta che la sua bella venga disturbata." },
      { id: 816, name: "L'Orfano", league: 5, power: 7, damage: 1, icon: "copy", ability: { trigger: "intervention", effect: "copyBonus", value: null }, description: "Potere: Intervento: Copia Bonus", flavour: "Figlio dell'odio della Megera, nato dal dolore e dalla delusione, è cresciuto fino ad arrivare ad una forma abominevole. Dentro di sé si sente però ancora come un bambino solo e abbandonato che attende il ritorno della madre." },
      { id: 817, name: "Aborto che Cammina", league: 4, power: 6, damage: 2, icon: "virus", ability: { trigger: "opportunista", effect: "enemyPower", value: -2, minPower: 3 }, description: "Potere: Opportunista: -2 POT nem. (min 3)", flavour: "Un feto cresciuto fuori dal grembo della sua madre. L'eredità della Megera lo ha cresciuto e ora non si fermerà più finché non sentirà di nuovo il tepore del ventre materno." },
      { id: 818, name: "Mangiamore", league: 3, power: 3, damage: 3, icon: "rat", ability: { trigger: "vendetta", effect: "power", value: 2 }, description: "Potere: Vendetta: +2 POT", flavour: "Un topo che si ciba dei cadaveri che riconosce. Mutato in un umanoide ratto che fa lo stesso — ma con gli affetti delle persone che conosce." },
      { id: 819, name: "Lettrice di Radici", league: 3, power: 3, damage: 3, icon: "wizard", ability: { trigger: "ultimaChance", effect: "enemyAssault", value: -13, minAssault: 5 }, description: "Potere: Ultima Chance: -13 VA nem. (min 5)", flavour: "Ebbe fede nella natura, ma non sapeva distinguere ciò che risiedeva sotto terra per protezione da chi vi risiedeva per esilio." },
      { id: 820, name: "Yata, lo Scalpo Alato", league: 2, power: 3, damage: 1, icon: "star", ability: { trigger: "turbo", effect: "assaultValue", value: 7 }, description: "Potere: Turbo: +7 VA", flavour: "Vola prima che il sole sorga. Arriva prima che il nemico sia pronto. Non aspetta — non sa cosa significhi aspettare." },
      { id: 821, name: "Bardo Sedotto", league: 2, power: 3, damage: 1, icon: "card", ability: { trigger: "glory", effect: "enemyDamage", value: -2, minDamage: 1 }, description: "Potere: Gloria: -2 DAN nem. (min 1)", flavour: "Cantava per le corti prima che la Megera gli sussurrasse il verso giusto. Quando vince, la melodia spezza le mani del nemico." },
      { id: 822, name: "Prete delle Malelabbra", league: 3, power: 4, damage: 3, icon: "devil", ability: { trigger: "rinforzi", effect: "toxin", value: 1, minHealth: 15 }, description: "Potere: Rinforzi: Tossina 1 (min 15)", flavour: "Benedice con parole che non dovrebbero uscire da una bocca umana. Quando la mano porta compagni della stessa lega, il veleno arriva prima della preghiera." },
      { id: 823, name: "Principe non più così Azzurro", league: 3, power: 4, damage: 3, icon: "crown", ability: { trigger: "invasione", effect: "enemyDamage", value: -2, minDamage: 1 }, description: "Potere: Invasione: -2 DAN nem. (min 1)", flavour: "Un tempo portava l'azzurro di Birgherund. Ora porta macchie e rancore — e quando avanza, il nemico dimentica come ferire." },
      { id: 824, name: "Camelo di T", league: 3, power: 3, damage: 2, icon: "insect", ability: { trigger: "sfida", effect: "assaultValue", value: 10 }, description: "Potere: Sfida: +10 VA", flavour: "Zoppica, sputa, rifiuta di fermarsi. Quando combatte sotto lega, la sua carovana di rancore travolge chi credeva di essere più grande." },
      { id: 825, name: "Maledizione Vivente: Ira", league: 3, power: 4, damage: 2, icon: "angry", ability: { trigger: "rimonta", effect: "enemyPowerAndDamage", value: -1, minPower: 3, minDamage: 3 }, description: "Potere: Rimonta: -1 POT, -1 DAN nem. (min 3)", flavour: "Non è un uomo maledetto — è la maledizione stessa, furiosa e senza nome. Quando resti indietro, strappa pezzi di forza al nemico." },
      { id: 826, name: "Principessa di Birgherund", league: 4, power: 4, damage: 1, icon: "crown", ability: { trigger: "rinforzi", effect: "enemyPower", value: -4, minPower: 1 }, description: "Potere: Rinforzi: -4 POT nem. (min 1)", flavour: "Corona storta, sorriso affilato. Quando nella mano c'è un alleato della stessa lega, il trono pesa sulle spalle nemiche." },
      { id: 827, name: "Cane da Guardia Reale", league: 4, power: 5, damage: 2, icon: "wolf", ability: { trigger: "resistenza", effect: "blockBonus", value: null }, description: "Potere: Resistenza: Blocca Bonus", flavour: "Ringhia solo quando il nemico conquista. Poi morde i vantaggi — non le gambe." },
      { id: 828, name: "Suora della Campa Fetida", league: 4, power: 5, damage: 3, icon: "pray", ability: { trigger: "lastWish", effect: "heal", value: 3 }, description: "Potere: Ultimo desiderio: Cura 3", flavour: "Prega tra tombe fresche e fango consacrato. Quando cade, la carne che resta guarisce — come se la morte fosse solo un rito incompleto." },
      { id: 829, name: "Carrozziere Fantasma", league: 4, power: 6, damage: 2, icon: "ghost", ability: { trigger: "invasione", effect: "assaultValue", value: 6 }, description: "Potere: Invasione: +6 VA", flavour: "Il carro non tocca terra. Quando avanza, il campo sotto di lui diventa un ponte di nebbia — e l'assalto arriva dall'altra sponda." },
      { id: 830, name: "Il Quarto Marito", league: 5, power: 6, damage: 3, icon: "skull", ability: { trigger: "magnanimous", effect: "attrition", value: 1, stat: "damage" }, description: "Potere: Magnanimo: Attrizione 1 DAN", flavour: "Tre matrimoni, tre funerali, una sola moglie che non perdonò mai. Quando vince contro chi è più debole, ogni carta già giocata diventa un colpo in più — lento, cumulativo, inevitabile." }
    ],

    // === PATTO DEGLI INDOCILI === (Tema: Fossa, ultrastrada, guerriglia urbana)
    // 30 carte · Lega 93 (11×L4 · 11×L3 · 8×L2)
    "Patto degli Indocili": [
      { id: 901, name: "Brutus, Campione della Fossa", league: 4, power: 5, damage: 3, icon: "angry", ability: { trigger: "sopraffare", effect: "powerAndDamage", value: 1 }, description: "Potere: Sopraffare: +1 POT, +1 DAN", flavour: "Gli stupidi credono che la sua forza sia nei pugni, la sua vera forza è nel terrore che rimane a chi sopravvive." },
      { id: 902, name: "Elysium, L'Immortale", league: 4, power: 4, damage: 2, icon: "robot", ability: { trigger: "overdrive", effect: "heal", value: 3 }, description: "Potere: Overdrive: Cura 3", flavour: "E' morto tante volte quante ha sbagliato, non ha mai smesso di rialzarsi e di sbagliare." },
      { id: 903, name: "KMD-30", league: 4, power: 4, damage: 4, icon: "rocket", ability: { trigger: "turbo", effect: "assaultValue", value: 9 }, description: "Potere: Turbo: +9 VA", flavour: "Si muove ad una velocita terrificante, nessuno lo ha mai visto fermo, nessuno ci ha mai parlato ma nessuno lo ha mai sfidato. Dicono che la sua umanita non ha retto la velocita a cui si e spinto ma quindi cosa lo muove?" },
      { id: 904, name: "Mr. Cavalca Via", league: 4, power: 6, damage: 1, icon: "wrench", ability: { trigger: "lastWish", effect: "directDamage", value: 3 }, description: "Potere: Ultimo desiderio: 3 Danni dir.", flavour: "Presidio i sotterannei convinto che il cielo gli potesse cadere addosso, disse addio al sole e alle parole." },
      { id: 905, name: "Napoleone VII", league: 4, power: 5, damage: 4, icon: "clipboard", ability: { trigger: "sfida", effect: "blockAbility", value: null }, description: "Potere: Sfida: Blocca Potere", flavour: "Secondo molti una persona dalla statura minuta guida quello che sembra essere un automa, nessuno ha mai potuto provarlo, nessuno che volesse continuare a vivere." },
      { id: 906, name: "Magnum l'Intrepido", league: 4, power: 4, damage: 3, icon: "moon", ability: { trigger: "intervention", effect: "enemyPower", value: -2, minPower: 4 }, description: "Potere: Intervento: -2 POT nem. (min 4)", flavour: "A differenza di quanto possa dire il nome, quell'uomo e tremendamente silenzioso." },
      { id: 907, name: "G.G.B.", league: 4, power: 5, damage: 3, icon: "horn", ability: { trigger: "imboscata", effect: "enemyAssault", value: -5, minAssault: 6 }, description: "Potere: Imboscata: -5 VA nem. (min 6)", flavour: "Fissato con la musica vecchio stile e con la pena di morte." },
      { id: 908, name: "Contrabbandiere di Fortuna", league: 3, power: 4, damage: 3, icon: "card", ability: { trigger: "intervention", effect: "focusCoin", value: 2 }, description: "Potere: Intervento: +2 FC", flavour: "Vende passaggi, nomi e silenzi. La sua fortuna e sapere sempre quale bugia vale piu della verita." },
      { id: 909, name: "Giustiziere Errante", league: 3, power: 5, damage: 1, icon: "skull", ability: { trigger: "vendetta", effect: "damage", value: 2 }, description: "Potere: Vendetta: +2 DAN", flavour: "Non ha un quartiere: ha una lista. Ogni volta che cade, torna con un nome in meno da cancellare." },
      { id: 910, name: "Cyber May Punk", league: 3, power: 4, damage: 1, icon: "sparkle", ability: { trigger: null, effect: "attrition", value: 1, stat: "damage" }, description: "Potere: Attrizione 1 DAN", flavour: "Porta il caos addosso come una bandiera. Quando tutti la danno per finita, il suo sorriso diventa una minaccia." },
      { id: 911, name: "Vandalo dell'Ultrastrada", league: 3, power: 4, damage: 2, icon: "rocket", ability: { trigger: "sfida", effect: "enemyPowerAndDamage", value: -1, minPower: 2, minDamage: 2 }, description: "Potere: Sfida: -1 POT, -1 DAN nem. (min 2)", flavour: "Scrive sentenze sui guardrail a tutta velocita. Dove passa lui, il traffico si ferma e la paura accelera." },
      { id: 912, name: "Repressore", league: 3, power: 3, damage: 3, icon: "block", ability: { trigger: "resistenza", effect: "power", value: 2 }, description: "Potere: Resistenza: +2 POT", flavour: "Ha imparato a non arretrare quando il fronte cede. Più la citta trema, più il suo braccio diventa pesante." },
      { id: 913, name: "Wraith dei Tunnel", league: 3, power: 4, damage: 2, icon: "ghost", ability: { trigger: "turbo", effect: "assaultValue", value: 6 }, description: "Potere: Turbo: +6 VA", flavour: "Nelle mappe ufficiali non esiste. Nelle notti di pioggia e lui che decide chi esce vivo dai sottopassi." },
      { id: 914, name: "Il Controllore", league: 3, power: 2, damage: 3, icon: "eye", ability: { trigger: "imboscata", effect: "enemyAssault", value: -12, minAssault: 10 }, description: "Potere: Imboscata: -12 VA nem. (min 10)", flavour: "Non urla, non corre, non sbaglia. Ti guarda una volta sola, e hai gia perso il diritto di scegliere." },
      { id: 915, name: "Predone della Fossa", league: 2, power: 3, damage: 1, icon: "card", ability: { trigger: "turbo", effect: "powerAndDamage", value: 1 }, description: "Potere: Turbo: +1 POT, +1 DAN", flavour: "Dalla Fossa ha imparato due cose: colpire per primo e sparire prima del conto." },
      { id: 916, name: "Regolatore di Debiti", league: 2, power: 2, damage: 1, icon: "warning", ability: { trigger: "ultimaChance", effect: "assaultValue", value: 9 }, description: "Potere: Ultima Chance: +9 VA", flavour: "Quando i conti non tornano, arriva lui. E alla fine torna sempre tutto, ma mai come speravi." },
      { id: 917, name: "Piromane dell'Ultrastrada", league: 2, power: 3, damage: 1, icon: "flame", ability: { trigger: null, effect: "escalation", value: 1, stat: "powerAndDamage" }, description: "Potere: Escalation 1 POT, 1 DAN", flavour: "Apre la notte con una scintilla. Il resto della strada fa il lavoro sporco al posto suo." },
      { id: 918, name: "Picchiatore di Infami", league: 2, power: 2, damage: 3, icon: "target", ability: { trigger: "rimonta", effect: "power", value: 2 }, description: "Potere: Rimonta: +2 POT", flavour: "Non cerca gloria, cerca bersagli. E in rimonta i bersagli diventano sempre più facili da trovare." },
      { id: 919, name: "Milizia del Grande Semaforo", league: 2, power: 2, damage: 2, icon: "lightning", ability: { trigger: "opportunista", effect: "power", value: 3 }, description: "Potere: Opportunista: +3 POT", flavour: "Aspettano il rosso perfetto: quello in cui l'altro accelera troppo e capisce tardi con chi ha a che fare." },
      { id: 920, name: "John, l'Idraulico", league: 2, power: 3, damage: 1, icon: "tower", ability: { trigger: "intervention", effect: "blockBonus", value: null }, description: "Potere: Intervento: Blocca Bonus", flavour: "Sorride, saluta, blocca tutto. E quando riparti, la tua armata non ha più la stessa voce." },
      { id: 921, name: "Lisa, la Promessa di Ferro", league: 2, power: 3, damage: 2, icon: "angry", ability: { trigger: "sfida", effect: "imponiPower", value: null }, description: "Potere: Sfida: Imponi POT", flavour: "Piccola di nome, enorme di rancore. Quando il Patto vacilla, è la prima a trasformare la paura in colpi." },
      { id: 922, name: "Schiavisti della Fossa", league: 2, power: 2, damage: 2, icon: "pickaxe", ability: { trigger: "invasione", effect: "enemyPowerAndDamage", value: -1, minPower: 3, minDamage: 3 }, description: "Potere: Invasione: -1 POT, -1 DAN nem. (min 3)", flavour: "Non liberano nessuno — trascinano tutti giù. Quando avanzano, anche i più forti scoprono di pesare come catene." },
      { id: 923, name: "Artista dell'Ultrastrada", league: 3, power: 3, damage: 2, icon: "sparkle", ability: { trigger: "rinforzi", effect: "copyAbility", value: null }, description: "Potere: Rinforzi: Copia Potere", flavour: "Dipingere non basta più: ruba gesti, incantesimi, minacce. Quando nella mano ci sono compagni del Patto, imita chiunque gli serva per finire l'opera." },
      { id: 924, name: "Vigile del Grande Semaforo", league: 3, power: 4, damage: 2, icon: "lightning", ability: { trigger: "opportunista", effect: "directDamage", value: 4 }, description: "Potere: Opportunista: 4 Danni dir.", flavour: "Controlla il rosso come altri controllano un coltello. Quando il nemico è in vantaggio, la multa arriva diretta — senza ricorso." },
      { id: 925, name: "Ultramezzo da Guerriglia", league: 3, power: 3, damage: 2, icon: "rocket", ability: { trigger: "overdrive", effect: "attrition", value: 1, stat: "power" }, description: "Potere: Overdrive: Attrizione 1 POT", flavour: "Corazzato, rumoroso, impossibile da ignorare. Quando il rito del Patto supera la soglia, ogni carta già giocata aggiunge peso al suo assalto." },
      { id: 926, name: "Mulo", league: 3, power: 4, damage: 2, icon: "gear", ability: { trigger: "turbo", effect: "blockBonus", value: null }, description: "Potere: Turbo: Blocca Bonus", flavour: "Carica senza chiedere permesso e senza fermarsi ai semafori. Nei primi respiri del duello, le ricompense nemiche restano chiuse nel carico." },
      { id: 927, name: "Bosozu, l'incendia-asfalto", league: 4, power: 4, damage: 3, icon: "flame", ability: { trigger: "rinforzi", effect: "directDamage", value: 3 }, description: "Potere: Rinforzi: 3 Danni dir.", flavour: "Motore urlante, strada in fiamme, sorriso sotto il casco. Quando la mano porta rinforzi, l'asfalto brucia prima ancora che tu possa sterzare." },
      { id: 928, name: "Il Multatore del Grande Semaforo", league: 4, power: 6, damage: 2, icon: "wrench", ability: { trigger: "opportunista", effect: "blockAbility", value: null }, description: "Potere: Opportunista: Blocca Potere", flavour: "Non ferma il traffico: ferma le intenzioni. Quando il nemico è in vantaggio, ogni potere resta inchiodato al rosso." },
      { id: 929, name: "King", league: 4, power: 5, damage: 4, icon: "crown", ability: { trigger: "resistenza", effect: "enemyDamage", value: -2, minDamage: 2 }, description: "Potere: Resistenza: -2 DAN nem. (min 2)", flavour: "Non regna sui vivi — regna su chi crede di aver già vinto. Quando conquistano, lui toglie al nemico il morso del colpo successivo." },
      { id: 930, name: "Dottor. Strada, CEO della Strade Enterprises", league: 4, power: 4, damage: 4, icon: "clipboard", ability: { trigger: "rimonta", effect: "enemyPowerAndDamage", value: -2, minPower: 3, minDamage: 3 }, description: "Potere: Rimonta: -2 POT, -2 DAN nem. (min 3)", flavour: "Possiede corsie, pedaggi e silenzi. Quando il Patto resta indietro, riduce il nemico alla misura che i suoi contratti consentono." }
    ],

    // === KHEMET === (Tema: Sigilli, riti, contenimento, imposizione)
    // Lega Totale: 75 (4×L5 · 9×L4 · 10×L3 · 7×L2)
    "Khemet": [
      { id: 1001, name: "Xer-Thael, Architetto dell'anima", league: 5, power: 5, damage: 3, icon: "ankh", ability: { trigger: "overdrive", effect: "powerAndDamage", value: 2 }, description: "Potere: Overdrive: +2 POT, +2 DAN", flavour: "Quando il Nono Sigillo si apre, la carne ricorda la legge antica e il mondo si piega alla forma del comando." },
      { id: 1002, name: "Zor-Amun, Naufrago dell'irrazionale", league: 5, power: 7, damage: 2, icon: "judge", ability: { trigger: "resistenza", effect: "imponiDamage", value: null }, description: "Potere: Resistenza: Imponi DAN", flavour: "Non condanna i colpevoli: riscrive il castigo. Ogni lama avversaria viene ridotta alla misura che lui decreta." },
      { id: 1003, name: "Maq-Reth, Padrone delle calamità", league: 5, power: 5, damage: 4, icon: "relic", ability: { trigger: "resistenza", effect: "focusCoin", value: 3 }, description: "Potere: Resistenza: +3 FC", flavour: "Conta monete che non esistono e debiti che nessuno osa saldare. Ogni perdita alimenta il prossimo rito." },
      { id: 1004, name: "Vel-Khar, il sigillatore", league: 4, power: 5, damage: 2, icon: "block", ability: { trigger: "turbo", effect: "blockAbility", value: null }, description: "Potere: Turbo: Blocca Potere", flavour: "Quando il varco si apre nei primi respiri del duello, la sua mano spezza la volontà prima ancora che diventi incantesimo." },
      { id: 1005, name: "Seth-Amon, il fattucchiere", league: 4, power: 4, damage: 4, icon: "scroll", ability: { trigger: "vendetta", effect: "power", value: 2 }, description: "Potere: Vendetta: +2 POT", flavour: "Scrive il tuo nome una sola volta. Al terzo scontro, la sua inchiostrazione diventa forza e il giudizio prende corpo." },
      { id: 1006, name: "Vor-Em, colui che può sapere", league: 4, power: 5, damage: 6, icon: "skull", ability: { trigger: null, effect: "imponiDamage", value: null }, description: "Potere: Imponi DAN", flavour: "Non alza la voce: impone una misura. Da quel momento, ogni ferita avversaria e grande solo quanto decide lui." },
      { id: 1007, name: "Iskaar-Taal, Capo delle forze di contenimento", league: 4, power: 4, damage: 5, icon: "lightning", ability: { trigger: "sfida", effect: "assaultValue", value: 12 }, description: "Potere: Sfida: +12 VA", flavour: "Contro i giganti non cerca scambio: cerca un varco. Quando e sottolega, il suo assalto diventa una sentenza fulminea." },
      { id: 1008, name: "Myrkrun-Khal, Arconte della non-morte", league: 4, power: 6, damage: 1, icon: "copy", ability: { trigger: "intervention", effect: "copyDamage", value: null }, description: "Potere: Intervento: Copia DAN", flavour: "Arriva secondo, osserva il colpo e lo riflette. Non aggiunge violenza: la ruba e la restituisce con precisione rituale." },
      { id: 1009, name: "Kah-Sef, Maestro runico", league: 3, power: 4, damage: 2, icon: "coin", ability: { trigger: "rimonta", effect: "focusCoin", value: 2 }, description: "Potere: Rimonta: +2 FC", flavour: "Quando Khemet arretra, lui raccoglie il prezzo di ogni crepa. Ogni perdita diventa carburante per il rito successivo." },
      { id: 1010, name: "Neb-Ra, il guardabisso", league: 3, power: 4, damage: 2, icon: "block", ability: { trigger: "intervention", effect: "enemyPower", value: -2, minPower: 2 }, description: "Potere: Intervento: -2 POT nem. (min 2)", flavour: "Parla solo dopo il primo impatto. E quando parla, la forza avversaria si piega fino al limite imposto dal Sigillo." },
      { id: 1011, name: "Ifret-Anhur, signora dei felini del caos", league: 3, power: 4, damage: 3, icon: "sword", ability: { trigger: "rimonta", effect: "damage", value: 3 }, description: "Potere: Rimonta: +3 DAN", flavour: "Scende per primo come una sentenza luminosa. Nel caos iniziale, la sua lama scrive il vantaggio in sangue e cenere." },
      { id: 1012, name: "Saqir-Mor, l'assorbi anima", league: 3, power: 2, damage: 4, icon: "copy", ability: { trigger: "overdrive", effect: "copyPower", value: null }, description: "Potere: Overdrive: Copia POT", flavour: "Non possiede forza propria: la ospita. Quando il rito supera la soglia, la potenza nemica diventa il suo vero corpo." },
      { id: 1013, name: "Mala-Kor, il Campione dell'Esterno", league: 3, power: 5, damage: 3, icon: "skull", ability: { trigger: "conquest", effect: "selfDamage", value: 4 }, description: "Potere: Conquista: -4 PV (a te)", flavour: "Vincere non e gratis. Ogni conquista pretende un tributo di carne, e lui paga sempre per primo." },
      { id: 1014, name: "Iseth-Vor, signore dei canidi dell'ordine", league: 3, power: 3, damage: 3, icon: "warning", ability: { trigger: "magnanimous", effect: "power", value: 3 }, description: "Potere: Magnanimo: +3 POT", flavour: "Quando il fronte vacilla, lui stringe la gola del nemico. Il colpo avversario non sparisce, ma torna a misura umana." },
      { id: 1015, name: "Akh-Sefer, l'Inverno nero", league: 2, power: 3, damage: 2, icon: "sword", ability: { trigger: "turbo", effect: "power", value: 2 }, description: "Potere: Turbo: +2 POT", flavour: "Nelle prime battute non attende segnali. Incide il sigillo nell'aria e travolge il campo prima che il nemico capisca il ritmo." },
      { id: 1016, name: "Kaal-Enf, impronta della Luna", league: 2, power: 2, damage: 2, icon: "copy", ability: { trigger: "rimonta", effect: "imponiPower", value: null }, description: "Potere: Rimonta: Imponi POT", flavour: "Quando Khemet resta indietro, il suo specchio non riflette il volto: riflette solo la forza utile a sopravvivere." },
      { id: 1017, name: "Qeb-Aru, Il Magister", league: 2, power: 3, damage: 1, icon: "rocket", ability: { trigger: "imboscata", effect: "powerAndDamage", value: 1 }, description: "Potere: Imboscata: +1 POT, +1 DAN", flavour: "Arriva per primo dal varco cianico, colpisce due volte e lascia dietro di sé solo sabbia nera e linee di sangue." },
      { id: 1018, name: "Prigioniero Khemet", league: 2, power: 4, damage: 2, icon: "skull", ability: { trigger: "conquest", effect: "selfDamage", value: 5 }, description: "Potere: Conquista: -5 PV (a te)", flavour: "Ogni vittoria che ottiene costa carne al suo evocatore. Non è un difetto: è il prezzo scritto nel patto." },
      { id: 1019, name: "Suiel-Herac, la smantellatrice", league: 2, power: 3, damage: 1, icon: "lightning", ability: { trigger: "sfida", effect: "assaultValue", value: 6 }, description: "Potere: Sfida: +6 VA", flavour: "Nato per sfidare chi è sopra di lui. Contro i titani non cerca onore: cerca il punto esatto dove affondare." },
      { id: 1020, name: "Ekon-Det, emissario delle piume", league: 2, power: 2, damage: 2, icon: "block", ability: { trigger: "intervention", effect: "power", value: 2 }, description: "Potere: Intervento: +2 POT", flavour: "Quando entra dopo il primo impatto, la sua magia non protegge: trasforma l'attesa in un colpo improvviso e brutale." },
      { id: 1021, name: "Alaz-Kahem, l'alchimista del sangue", league: 2, power: 3, damage: 1, icon: "relic", ability: { trigger: "magnanimous", effect: "focusCoin", value: 2 }, description: "Potere: Magnanimo: +2 FC", flavour: "Distilla monete dal sangue altrui — ma solo quando Khemet è in salute. La sua alchimia non perdona chi è già in ginocchio." },
      { id: 1022, name: "Bazif-shu'r, scriba delle formule minori di contenimento", league: 3, power: 4, damage: 2, icon: "scroll", ability: { trigger: "glory", effect: "blockBonus", value: null }, description: "Potere: Gloria: Blocca Bonus", flavour: "Scrive sigilli piccoli, quasi educati. Quando vince, le formule si chiudono sulle ricompense nemiche come coperchi di pietra." },
      { id: 1023, name: "Hekwa-sew, lo scultore osseo", league: 3, power: 4, damage: 2, icon: "skull", ability: { trigger: "invasione", effect: "powerAndDamage", value: 1 }, description: "Potere: Invasione: +1 POT, +1 DAN", flavour: "Modella carne e calcagno con la stessa pazienza. Quando avanza, ogni osso che scolpisce diventa un colpo in più sul campo." },
      { id: 1024, name: "Nejiro-sa'er, la bestia magica", league: 3, power: 4, damage: 3, icon: "wolf", ability: { trigger: "imboscata", effect: "assaultValue", value: 6 }, description: "Potere: Imboscata: +6 VA", flavour: "Non è un animale sigillato — è il sigillo che ha imparato a mordere. Arriva per primo e il varco si apre come una gola." },
      { id: 1025, name: "Cerjekarauhul, collaudatore del tempo", league: 3, power: 3, damage: 2, icon: "warning", ability: { trigger: "ultimaChance", effect: "assaultValue", value: 12 }, description: "Potere: Ultima Chance: +12 VA", flavour: "Misura ogni istante finché la partita non resta a un solo respiro. Quando il tempo scade, il suo assalto diventa una sentenza fuori calendario." },
      { id: 1026, name: "Aesimojof, arconte del clima", league: 4, power: 6, damage: 1, icon: "lightning", ability: { trigger: "reckoning", effect: "imponiDamage", value: null }, description: "Potere: Resa dei conti: Imponi DAN", flavour: "Tempeste, siccità, grandine — tutto obbedisce al suo registro. Quando il conto è pari, impone al nemico la misura esatta del dolore." },
      { id: 1027, name: "Jahma-Ferezev, astrologo dell'orrore", league: 4, power: 6, damage: 1, icon: "eye", ability: { trigger: "reckoning", effect: "attrition", value: 1, stat: "damage" }, description: "Potere: Resa dei conti: Attrizione 1 DAN", flavour: "Legge nel cielo ciò che ancora non è accaduto. Quando entrambi hanno giocato abbastanza, ogni carta passata pesa sul danno nemico come un presagio." },
      { id: 1028, name: "Gar'Zet-Zal, Comandante dei Magus", league: 4, power: 4, damage: 3, icon: "sword", ability: { trigger: "imboscata", effect: "attrition", value: 1, stat: "power" }, description: "Potere: Imboscata: Attrizione 1 POT", flavour: "Comanda dal varco, non dal trono. Ogni mago già schierato diventa un filo della sua imboscata — e la potenza cresce senza rumore." },
      { id: 1029, name: "Maju-Label'la, magister del controllo", league: 4, power: 5, damage: 3, icon: "block", ability: { trigger: "sopraffare", effect: "enemyPower", value: -2, minPower: 2 }, description: "Potere: Sopraffare: -2 POT nem. (min 2)", flavour: "Non spezza le catene: le stringe. Quando la lega di Khemet domina, la forza avversaria si piega fino al limite che lui consente." },
      { id: 1030, name: "Ashigotte, il primo maestro", league: 5, power: 6, damage: 3, icon: "ankh", ability: { trigger: "overdrive", effect: "blockAbility", value: null }, description: "Potere: Overdrive: Blocca Potere", flavour: "Prima di Xer-Thael, prima dei sigilli scritti — c'era lui. Quando il rito supera la soglia, la volontà nemica non trova più parole." }
    ]
  };
  
